def list_issue_types(project_id, status=None, is_default=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        path2 = os.path.join(_DB, "usage_counters.json")
        if not os.path.exists(path2):
            _save("usage_counters.json", [])
        return _load("request_logs.json"), _load("usage_counters.json")

    def _log(endpoint, status_code, credential_id=None, meta=None):
        logs, counters = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "pln_req_" + hashlib.sha256((endpoint + now + str(latency_ms) + str(len(logs))).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

        # Best-effort counters
        key = "global"
        found = None
        for r in counters:
            if r.get("id") == key:
                found = r
                break
        if not found:
            found = {"id": key, "day": now[:10], "total_requests": 0, "total_mutations": 0, "updated_at": now}
            counters.append(found)
        if found.get("day") != now[:10]:
            found["day"] = now[:10]
            found["total_requests"] = 0
            found["total_mutations"] = 0
        found["total_requests"] = int(found.get("total_requests") or 0) + 1
        found["updated_at"] = now
        _save("usage_counters.json", counters)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        # Simple global limit: 120 requests / 60s
        cutoff = time.time() - 60
        cnt = 0
        for r in reversed(logs):
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() < cutoff:
                    break
                cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=120)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("list_issue_types", "RATE_LIMIT", meta={"project_id": project_id})
        return rl

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]{4}.*$", project_id or ""):
        out = _err("VALIDATION_ERROR", "project_id is missing or invalid.", field="project_id")
        _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
        return out

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            out = _err("VALIDATION_ERROR", "Unsupported status filter.", field="status", allowed=["active", "archived", "deleted"])
            _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
            return out

    if is_default is not None and not isinstance(is_default, bool):
        out = _err("VALIDATION_ERROR", "is_default must be a boolean.", field="is_default")
        _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
        return out

    if search is not None and not isinstance(search, str):
        out = _err("VALIDATION_ERROR", "search must be a string.", field="search")
        _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
        return out

    if sort_by is None:
        sort_by = "sort_order"
    if sort_order is None:
        sort_order = "asc"

    if sort_by not in ("sort_order", "name", "created_at", "updated_at"):
        out = _err("VALIDATION_ERROR", "Unsupported sort_by value.", field="sort_by", allowed=["sort_order", "name", "created_at", "updated_at"])
        _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
        return out
    if sort_order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "Unsupported sort_order value.", field="sort_order", allowed=["asc", "desc"])
        _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
        return out

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
        _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
        return out

    # Ambient auth: find any active membership for any active user for the workspace owning the project.
    users = _load("users.json")
    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    memberships = _load("workspace_users.json")
    entities = _load("project_entities.json")

    proj = None
    for p in projects:
        if p.get("id") == project_id:
            proj = p
            break
    if not proj:
        # Reads return empty only for filters; missing project is an auth/not_found scenario; vendor describes VALIDATION only for invalid id, not missing.
        out = _err("NOT_FOUND", "Project not found.", project_id=project_id)
        _log("list_issue_types", "NOT_FOUND", meta={"project_id": project_id})
        return out

    ws_id = proj.get("workspace_id")
    ws = None
    for w in workspaces:
        if w.get("id") == ws_id:
            ws = w
            break
    if not ws or ws.get("status") not in ("active", "archived"):
        out = _err("UNAUTHORIZED", "Not authenticated for a workspace that can serve this request.")
        _log("list_issue_types", "UNAUTHORIZED", meta={"project_id": project_id})
        return out

    allowed_user_ids = set(u["id"] for u in users if u.get("status") == "active")
    ok = False
    for m in memberships:
        if m.get("workspace_id") == ws_id and m.get("status") == "active" and m.get("user_id") in allowed_user_ids:
            ok = True
            break
    if not ok:
        out = _err("UNAUTHORIZED", "You do not have access to the parent project.")
        _log("list_issue_types", "UNAUTHORIZED", meta={"project_id": project_id})
        return out

    # Cursor decode
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 4096:
            out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
            return out
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if payload.get("v") != 1 or payload.get("project_id") != project_id:
                raise ValueError("bad cursor")
            start_after = payload.get("after")
        except Exception:
            out = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            _log("list_issue_types", "VALIDATION_ERROR", meta={"project_id": project_id})
            return out

    # Filter
    s = (search or "").strip().lower()
    rows = []
    for e in entities:
        if e.get("project_id") != project_id:
            continue
        if e.get("entity_type") != "issue_type":
            continue
        if e.get("status") == "deleted":
            continue  # tool may accept status=deleted but business rule says list_* returns status != 'deleted'
        if status is not None and e.get("status") != status:
            continue
        if is_default is not None and bool(e.get("is_default")) != is_default:
            continue
        if s:
            name = (e.get("name") or "").lower()
            desc = (e.get("description") or "").lower()
            if s not in name and s not in desc:
                continue
        rows.append(e)

    # Sort
    def _k(r):
        v = r.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            return v or ""
        if sort_by == "name":
            return (v or "").lower()
        if sort_by == "sort_order":
            # None last for asc, first for desc
            return (float("inf") if v is None else v)
        return v

    rev = (sort_order == "desc")
    if sort_by == "sort_order":
        rows.sort(key=lambda r: (_k(r), (r.get("name") or "").lower(), r.get("id") or ""), reverse=rev)
    else:
        rows.sort(key=lambda r: (_k(r), r.get("id") or ""), reverse=rev)

    # Pagination using start_after as index into stable ordering by id+sort key
    start_idx = 0
    if start_after:
        # start_after is last seen entity id
        for i, r in enumerate(rows):
            if r.get("id") == start_after:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        payload = {"v": 1, "project_id": project_id, "after": page[-1].get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    out = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log("list_issue_types", "OK", meta={"project_id": project_id, "returned": len(page)})
    return out

def get_issue_type(issue_type_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        path2 = os.path.join(_DB, "usage_counters.json")
        if not os.path.exists(path2):
            _save("usage_counters.json", [])
        return _load("request_logs.json"), _load("usage_counters.json")

    def _log(endpoint, status_code, meta=None):
        logs, counters = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "pln_req_" + hashlib.sha256((endpoint + now + str(latency_ms) + str(len(logs))).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)
        key = "global"
        found = None
        for r in counters:
            if r.get("id") == key:
                found = r
                break
        if not found:
            found = {"id": key, "day": now[:10], "total_requests": 0, "total_mutations": 0, "updated_at": now}
            counters.append(found)
        if found.get("day") != now[:10]:
            found["day"] = now[:10]
            found["total_requests"] = 0
            found["total_mutations"] = 0
        found["total_requests"] = int(found.get("total_requests") or 0) + 1
        found["updated_at"] = now
        _save("usage_counters.json", counters)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        cutoff = time.time() - 60
        cnt = 0
        for r in reversed(logs):
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() < cutoff:
                    break
                cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=120)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("get_issue_type", "RATE_LIMIT", meta={"issue_type_id": issue_type_id})
        return rl

    if not isinstance(issue_type_id, str) or not re.match(r"^pln_ent_[0-9A-Z]{4}.*$", issue_type_id or ""):
        out = _err("VALIDATION_ERROR", "issue_type_id is missing or invalid.", field="issue_type_id")
        _log("get_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id})
        return out

    users = _load("users.json")
    memberships = _load("workspace_users.json")
    projects = _load("projects.json")
    workspaces = _load("workspaces.json")
    entities = _load("project_entities.json")

    ent = None
    for e in entities:
        if e.get("id") == issue_type_id:
            ent = e
            break
    if not ent or ent.get("entity_type") != "issue_type" or ent.get("status") == "deleted":
        out = _err("NOT_FOUND", "Issue type not found.", issue_type_id=issue_type_id)
        _log("get_issue_type", "NOT_FOUND", meta={"issue_type_id": issue_type_id})
        return out

    proj = None
    for p in projects:
        if p.get("id") == ent.get("project_id"):
            proj = p
            break
    if not proj:
        out = _err("NOT_FOUND", "Parent project not found.", project_id=ent.get("project_id"))
        _log("get_issue_type", "NOT_FOUND", meta={"issue_type_id": issue_type_id})
        return out

    ws = None
    for w in workspaces:
        if w.get("id") == proj.get("workspace_id"):
            ws = w
            break
    if not ws or ws.get("status") not in ("active", "archived"):
        out = _err("UNAUTHORIZED", "Not authenticated.")
        _log("get_issue_type", "UNAUTHORIZED", meta={"issue_type_id": issue_type_id})
        return out

    allowed_user_ids = set(u["id"] for u in users if u.get("status") == "active")
    ok = False
    for m in memberships:
        if m.get("workspace_id") == ws.get("id") and m.get("status") == "active" and m.get("user_id") in allowed_user_ids:
            ok = True
            break
    if not ok:
        out = _err("UNAUTHORIZED", "You do not have access to the parent project.")
        _log("get_issue_type", "UNAUTHORIZED", meta={"issue_type_id": issue_type_id})
        return out

    out = {"data": ent}
    _log("get_issue_type", "OK", meta={"issue_type_id": issue_type_id, "project_id": ent.get("project_id")})
    return out

def create_issue_type(project_id, name, description=None, color=None, sort_order=None, is_default=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        path2 = os.path.join(_DB, "usage_counters.json")
        if not os.path.exists(path2):
            _save("usage_counters.json", [])
        return _load("request_logs.json"), _load("usage_counters.json")

    def _log(endpoint, status_code, meta=None, mutation=False):
        logs, counters = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "pln_req_" + hashlib.sha256((endpoint + now + str(latency_ms) + str(len(logs))).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)
        key = "global"
        found = None
        for r in counters:
            if r.get("id") == key:
                found = r
                break
        if not found:
            found = {"id": key, "day": now[:10], "total_requests": 0, "total_mutations": 0, "updated_at": now}
            counters.append(found)
        if found.get("day") != now[:10]:
            found["day"] = now[:10]
            found["total_requests"] = 0
            found["total_mutations"] = 0
        found["total_requests"] = int(found.get("total_requests") or 0) + 1
        if mutation:
            found["total_mutations"] = int(found.get("total_mutations") or 0) + 1
        found["updated_at"] = now
        _save("usage_counters.json", counters)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        cutoff = time.time() - 60
        cnt = 0
        for r in reversed(logs):
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() < cutoff:
                    break
                cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=120)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("create_issue_type", "RATE_LIMIT", meta={"project_id": project_id}, mutation=True)
        return rl

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]{4}.*$", project_id or ""):
        out = _err("VALIDATION_ERROR", "project_id is missing or invalid.", field="project_id")
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    if not isinstance(name, str) or len(name.strip()) < 1:
        out = _err("VALIDATION_ERROR", "name is required and must be non-empty.", field="name")
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    name = name.strip()

    if description is not None and not isinstance(description, str):
        out = _err("VALIDATION_ERROR", "description must be a string.", field="description")
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    if color is not None:
        if not isinstance(color, str):
            out = _err("VALIDATION_ERROR", "color must be a string.", field="color")
            _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
            return out
        if not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            out = _err("VALIDATION_ERROR", "color must match ^#?[0-9A-Fa-f]{6}$.", field="color")
            _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
            return out
        if not color.startswith("#"):
            color = "#" + color

    if sort_order is not None and not isinstance(sort_order, (int, float)):
        out = _err("VALIDATION_ERROR", "sort_order must be a number.", field="sort_order")
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    if is_default is not None and not isinstance(is_default, bool):
        out = _err("VALIDATION_ERROR", "is_default must be a boolean.", field="is_default")
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
        out = _err("VALIDATION_ERROR", "Unsupported status value.", field="status", allowed=["active", "archived", "deleted"])
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    if status == "deleted":
        out = _err("VALIDATION_ERROR", "Cannot create an issue type with status='deleted'.", field="status")
        _log("create_issue_type", "VALIDATION_ERROR", meta={"project_id": project_id}, mutation=True)
        return out
    if is_default is None:
        is_default = False

    users = _load("users.json")
    memberships = _load("workspace_users.json")
    projects = _load("projects.json")
    workspaces = _load("workspaces.json")
    entities = _load("project_entities.json")

    proj = None
    for p in projects:
        if p.get("id") == project_id:
            proj = p
            break
    if not proj:
        out = _err("NOT_FOUND", "Project not found.", project_id=project_id)
        _log("create_issue_type", "NOT_FOUND", meta={"project_id": project_id}, mutation=True)
        return out

    ws_id = proj.get("workspace_id")
    ws = None
    for w in workspaces:
        if w.get("id") == ws_id:
            ws = w
            break
    if not ws:
        out = _err("UNAUTHORIZED", "Not authenticated.")
        _log("create_issue_type", "UNAUTHORIZED", meta={"project_id": project_id}, mutation=True)
        return out

    # Mutations forbidden if authenticated principal is disabled; with ambient auth, choose an active user that satisfies permissions.
    active_users = [u for u in users if u.get("status") == "active"]
    if not active_users:
        out = _err("UNAUTHORIZED", "Not authenticated.")
        _log("create_issue_type", "UNAUTHORIZED", meta={"project_id": project_id}, mutation=True)
        return out

    acting_user_id = None
    acting_role = None
    for m in memberships:
        if m.get("workspace_id") == ws_id and m.get("status") == "active" and m.get("role") in ("owner", "admin"):
            uid = m.get("user_id")
            if any(u.get("id") == uid and u.get("status") == "active" for u in users):
                acting_user_id = uid
                acting_role = m.get("role")
                break
    if not acting_user_id:
        out = _err("UNAUTHORIZED", "You lack permission to manage the project.")
        _log("create_issue_type", "UNAUTHORIZED", meta={"project_id": project_id}, mutation=True)
        return out

    # Uniqueness: unique(project_id, entity_type, name) where status != 'deleted'
    for e in entities:
        if e.get("project_id") == project_id and e.get("entity_type") == "issue_type" and e.get("status") != "deleted":
            if (e.get("name") or "") == name:
                out = _err("CONFLICT", "An issue type with this name already exists in the project.", field="name")
                _log("create_issue_type", "CONFLICT", meta={"project_id": project_id}, mutation=True)
                return out

    # Create id
    def _new_id(prefix):
        rand = "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(10))
        return prefix + rand

    new_id = _new_id("pln_ent_")
    existing_ids = set(e.get("id") for e in entities)
    while new_id in existing_ids:
        new_id = _new_id("pln_ent_")

    # Exactly one default per project/entity_type: if setting new default, unset old default (in same "transaction")
    if is_default:
        changed = False
        for e in entities:
            if e.get("project_id") == project_id and e.get("entity_type") == "issue_type" and e.get("status") != "deleted" and e.get("is_default") is True:
                e["is_default"] = False
                e["updated_at"] = now
                e["updated_by_user_id"] = acting_user_id
                changed = True
        if changed:
            _save("project_entities.json", entities)
            entities = _load("project_entities.json")

    rec = {
        "id": new_id,
        "project_id": project_id,
        "entity_type": "issue_type",
        "name": name,
        "description": description,
        "status": status,
        "sort_order": sort_order,
        "color": color,
        "state_category": None,
        "is_default": bool(is_default),
        "cycle_start_at": None,
        "cycle_end_at": None,
        "module_lead_user_id": None,
        "created_at": now,
        "updated_at": now,
        "created_by_user_id": acting_user_id,
        "updated_by_user_id": acting_user_id
    }

    entities.append(rec)
    _save("project_entities.json", entities)
    _log("create_issue_type", "OK", meta={"project_id": project_id, "issue_type_id": new_id, "role": acting_role}, mutation=True)
    return {"data": rec}

def update_issue_type(issue_type_id, name=None, description=None, color=None, sort_order=None, is_default=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        path2 = os.path.join(_DB, "usage_counters.json")
        if not os.path.exists(path2):
            _save("usage_counters.json", [])
        return _load("request_logs.json"), _load("usage_counters.json")

    def _log(endpoint, status_code, meta=None, mutation=False):
        logs, counters = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "pln_req_" + hashlib.sha256((endpoint + now + str(latency_ms) + str(len(logs))).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)
        key = "global"
        found = None
        for r in counters:
            if r.get("id") == key:
                found = r
                break
        if not found:
            found = {"id": key, "day": now[:10], "total_requests": 0, "total_mutations": 0, "updated_at": now}
            counters.append(found)
        if found.get("day") != now[:10]:
            found["day"] = now[:10]
            found["total_requests"] = 0
            found["total_mutations"] = 0
        found["total_requests"] = int(found.get("total_requests") or 0) + 1
        if mutation:
            found["total_mutations"] = int(found.get("total_mutations") or 0) + 1
        found["updated_at"] = now
        _save("usage_counters.json", counters)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        cutoff = time.time() - 60
        cnt = 0
        for r in reversed(logs):
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() < cutoff:
                    break
                cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=120)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("update_issue_type", "RATE_LIMIT", meta={"issue_type_id": issue_type_id}, mutation=True)
        return rl

    if not isinstance(issue_type_id, str) or not re.match(r"^pln_ent_[0-9A-Z]{4}.*$", issue_type_id or ""):
        out = _err("VALIDATION_ERROR", "issue_type_id is missing or invalid.", field="issue_type_id")
        _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    if name is not None:
        if not isinstance(name, str) or len(name.strip()) < 1:
            out = _err("VALIDATION_ERROR", "name must be non-empty when provided.", field="name")
            _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
            return out
        name = name.strip()

    if description is not None and not isinstance(description, str):
        out = _err("VALIDATION_ERROR", "description must be a string.", field="description")
        _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    if color is not None:
        if not isinstance(color, str):
            out = _err("VALIDATION_ERROR", "color must be a string.", field="color")
            _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
            return out
        if not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            out = _err("VALIDATION_ERROR", "color must match ^#?[0-9A-Fa-f]{6}$.", field="color")
            _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
            return out
        if not color.startswith("#"):
            color = "#" + color

    if sort_order is not None and not isinstance(sort_order, (int, float)):
        out = _err("VALIDATION_ERROR", "sort_order must be a number.", field="sort_order")
        _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    if is_default is not None and not isinstance(is_default, bool):
        out = _err("VALIDATION_ERROR", "is_default must be a boolean.", field="is_default")
        _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            out = _err("VALIDATION_ERROR", "Unsupported status value.", field="status", allowed=["active", "archived", "deleted"])
            _log("update_issue_type", "VALIDATION_ERROR", meta={"issue_type_id": issue_type_id}, mutation=True)
            return out

    users = _load("users.json")
    memberships = _load("workspace_users.json")
    projects = _load("projects.json")
    workspaces = _load("workspaces.json")
    entities = _load("project_entities.json")
    issues = _load("issues.json")

    ent = None
    ent_idx = None
    for i, e in enumerate(entities):
        if e.get("id") == issue_type_id:
            ent = e
            ent_idx = i
            break
    if not ent or ent.get("entity_type") != "issue_type":
        out = _err("NOT_FOUND", "Issue type not found.", issue_type_id=issue_type_id)
        _log("update_issue_type", "NOT_FOUND", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    proj = None
    for p in projects:
        if p.get("id") == ent.get("project_id"):
            proj = p
            break
    if not proj:
        out = _err("NOT_FOUND", "Parent project not found.", project_id=ent.get("project_id"))
        _log("update_issue_type", "NOT_FOUND", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    ws = None
    for w in workspaces:
        if w.get("id") == proj.get("workspace_id"):
            ws = w
            break
    if not ws:
        out = _err("UNAUTHORIZED", "Not authenticated.")
        _log("update_issue_type", "UNAUTHORIZED", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    # Pick an acting user with permission owner/admin and active user status; disabled users cannot mutate.
    acting_user_id = None
    for m in memberships:
        if m.get("workspace_id") == ws.get("id") and m.get("status") == "active" and m.get("role") in ("owner", "admin"):
            uid = m.get("user_id")
            for u in users:
                if u.get("id") == uid:
                    if u.get("status") != "active":
                        continue
                    acting_user_id = uid
                    break
        if acting_user_id:
            break
    if not acting_user_id:
        out = _err("UNAUTHORIZED", "You don’t have permission to update the parent project.")
        _log("update_issue_type", "UNAUTHORIZED", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    # Validate lifecycle transition if status provided
    if status is not None:
        cur = ent.get("status")
        allowed = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
        if cur != status:
            if status not in allowed.get(cur, []):
                out = _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)
                _log("update_issue_type", "INVALID_TRANSITION", meta={"issue_type_id": issue_type_id}, mutation=True)
                return out
        # Soft delete constraints: cannot delete if referenced by any issue.issue_type_id
        if status == "deleted" and cur != "deleted":
            for iss in issues:
                if iss.get("project_id") == ent.get("project_id") and iss.get("status") != "deleted" and iss.get("issue_type_id") == issue_type_id:
                    out = _err("CONFLICT", "Cannot delete issue type because it is referenced by issues.", issue_type_id=issue_type_id)
                    _log("update_issue_type", "CONFLICT", meta={"issue_type_id": issue_type_id}, mutation=True)
                    return out

    # Name uniqueness if changed
    if name is not None:
        for e in entities:
            if e.get("id") == issue_type_id:
                continue
            if e.get("project_id") == ent.get("project_id") and e.get("entity_type") == "issue_type" and e.get("status") != "deleted":
                if (e.get("name") or "") == name:
                    out = _err("CONFLICT", "An issue type with this name already exists in the project.", field="name")
                    _log("update_issue_type", "CONFLICT", meta={"issue_type_id": issue_type_id}, mutation=True)
                    return out

    # Apply updates
    updated = dict(ent)
    if name is not None:
        updated["name"] = name
    if description is not None:
        updated["description"] = description
    if color is not None:
        updated["color"] = color
    if sort_order is not None:
        updated["sort_order"] = sort_order
    if is_default is not None:
        updated["is_default"] = bool(is_default)

    if status is not None:
        updated["status"] = status

    # Enforce exactly one default per project/entity_type when toggling to default true (and not deleted)
    if is_default is True and updated.get("status") != "deleted":
        for i, e in enumerate(entities):
            if e.get("project_id") == updated.get("project_id") and e.get("entity_type") == "issue_type" and e.get("status") != "deleted":
                if e.get("id") != issue_type_id and e.get("is_default") is True:
                    entities[i]["is_default"] = False
                    entities[i]["updated_at"] = now
                    entities[i]["updated_by_user_id"] = acting_user_id

    updated["updated_at"] = now
    updated["updated_by_user_id"] = acting_user_id

    # If marking deleted, also must not remain default
    if updated.get("status") == "deleted":
        updated["is_default"] = False

    # No success without effect
    if updated == ent:
        out = _err("CONFLICT", "No changes to apply.")
        _log("update_issue_type", "CONFLICT", meta={"issue_type_id": issue_type_id}, mutation=True)
        return out

    entities[ent_idx] = updated
    _save("project_entities.json", entities)

    _log("update_issue_type", "OK", meta={"issue_type_id": issue_type_id, "project_id": updated.get("project_id")}, mutation=True)
    return {"data": updated}

def delete_issue_type(issue_type_id, **_extra):
    import json, os, datetime, time, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_issue_type"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, principal_user_id=None, workspace_id=None, project_id=None, entity_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "entity_id": entity_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(issue_type_id, str) or not re.match(r"^pln_ent_[0-9A-Z]{4}.*$", issue_type_id or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "issue_type_id is missing or invalid"})
            return _err("VALIDATION_ERROR", "issue_type_id is missing or invalid", issue_type_id=issue_type_id)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        entities = _load("project_entities.json")
        if not isinstance(entities, list): entities = []
        ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == issue_type_id), None)
        if not ent or ent.get("entity_type") != "issue_type":
            _log("error", principal_user_id=principal_user_id, entity_id=issue_type_id, error={"code": "NOT_FOUND", "message": "Issue type not found"})
            return _err("NOT_FOUND", "Issue type not found", issue_type_id=issue_type_id)

        if ent.get("status") == "deleted":
            _log("success", principal_user_id=principal_user_id, project_id=ent.get("project_id"), entity_id=issue_type_id)
            return {"data": {"id": issue_type_id, "deleted": True, "status": "deleted"}}

        project_id = ent.get("project_id")
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log("error", principal_user_id=principal_user_id, project_id=project_id, entity_id=issue_type_id, error={"code": "NOT_FOUND", "message": "Parent project not found"})
            return _err("NOT_FOUND", "Parent project not found", project_id=project_id)

        wsp_id = prj.get("workspace_id")
        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []
        membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == wsp_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
        if not membership:
            _log("error", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=issue_type_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership for this project."})
            return _err("UNAUTHORIZED", "No active workspace membership for this project.", workspace_id=wsp_id, project_id=project_id)

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        for iss in issues:
            if not isinstance(iss, dict): 
                continue
            if iss.get("status") == "deleted":
                continue
            if iss.get("project_id") != project_id:
                continue
            if iss.get("issue_type_id") == issue_type_id:
                _log("error", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=issue_type_id, error={"code": "CONFLICT", "message": "Issue type is referenced by existing issues and cannot be deleted."})
                return _err("CONFLICT", "Issue type is referenced by existing issues and cannot be deleted.", issue_type_id=issue_type_id)

        now = _now()
        for e in entities:
            if isinstance(e, dict) and e.get("id") == issue_type_id:
                e["status"] = "deleted"
                e["updated_at"] = now
                e["updated_by_user_id"] = principal_user_id
                break

        _save("project_entities.json", entities)

        _log("success", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=issue_type_id)
        return {"data": {"id": issue_type_id, "entity_type": "issue_type", "status": "deleted", "deleted": True, "project_id": project_id, "updated_at": now}}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

