        q = search.strip().lower()
        if q:
            def _hay(e):
                return ((e.get("name") or "") + " " + (e.get("description") or "")).lower()
            rows = [e for e in rows if q in _hay(e)]

    # Sorting
    reverse = (sort_order == "desc")
    def _key(e):
        v = e.get(sort_by)
        if v is None:
            # push nulls last for asc, first for desc
            return (1, "")
        return (0, v)
    try:
        rows.sort(key=_key, reverse=reverse)
    except TypeError:
        # if mixed types somehow, fall back to name
        rows.sort(key=lambda e: (e.get("name") or ""), reverse=reverse)

    total = len(rows)

    # Cursor pagination (opaque): base64 of integer offset
    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(decoded.decode("utf-8"))
            if offset < 0: offset = 0
        except Exception:
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("ok")
    return resp

def get_state(state_id, **_extra):
