def create_state(project_id, name, state_category, description=None, color=None, sort_order=None, is_default=None, status=None, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    users = _load("users.json")
    authed_user = next((u for u in users if u.get("status") == "active"), None)
    request_log = _load("request_log.json")
    usage = _load("usage.json")

    def _log(status_s, code=None, message=None, extra=None):
        nonlocal request_log, usage
        row = {
            "id": f"pln_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "create_state",
            "timestamp": _now,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
            "user_id": authed_user.get("id") if isinstance(authed_user, dict) else None,
        }
        if code: row["error_code"] = code
        if message: row["error_message"] = message
        if extra and isinstance(extra, dict): row.update(extra)
        if not isinstance(request_log, list): request_log = []
        request_log.append(row)
        try:
            _save("request_log.json", request_log)
        except Exception:
            pass
        if isinstance(usage, dict):
            usage["calls_total"] = int(usage.get("calls_total", 0) or 0) + 1
            usage["calls_create_state"] = int(usage.get("calls_create_state", 0) or 0) + 1
            try:
                _save("usage.json", usage)
            except Exception:
                pass

    # Validate inputs
    if not isinstance(project_id, str) or not project_id:
        _log("error", "VALIDATION_ERROR", "project_id is required")
        return _err("VALIDATION_ERROR", "project_id is required")
    if not re.match(r"^pln_prj_[0-9A-Z]{4}.*$", project_id):
        _log("error", "VALIDATION_ERROR", "project_id has invalid format")
        return _err("VALIDATION_ERROR", "project_id has invalid format")

    if not isinstance(name, str) or len(name.strip()) < 1:
        _log("error", "VALIDATION_ERROR", "name is required")
        return _err("VALIDATION_ERROR", "name is required")
    name = name.strip()

    allowed_cat = {"backlog", "unstarted", "started", "completed", "cancelled"}
    if not isinstance(state_category, str) or state_category not in allowed_cat:
        _log("error", "VALIDATION_ERROR", "Unsupported state_category")
        return _err("VALIDATION_ERROR", "Unsupported state_category")

    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR", "description must be a string")
        return _err("VALIDATION_ERROR", "description must be a string")

    if color is not None:
        if not isinstance(color, str):
            _log("error", "VALIDATION_ERROR", "color must be a string")
            return _err("VALIDATION_ERROR", "color must be a string")
        if not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            _log("error", "VALIDATION_ERROR", "color has invalid format")
            return _err("VALIDATION_ERROR", "color has invalid format")

    if sort_order is not None and not isinstance(sort_order, (int, float)):
        _log("error", "VALIDATION_ERROR", "sort_order must be a number")
        return _err("VALIDATION_ERROR", "sort_order must be a number")

    if is_default is None:
        is_default = False
    if not isinstance(is_default, bool):
        _log("error", "VALIDATION_ERROR", "is_default must be boolean")
        return _err("VALIDATION_ERROR", "is_default must be boolean")

    allowed_status = {"active", "archived", "deleted"}
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", "VALIDATION_ERROR", "Unsupported status")
        return _err("VALIDATION_ERROR", "Unsupported status")
    if status == "deleted":
        # creation into deleted doesn't make sense for this backend; treat as validation error
        _log("error", "VALIDATION_ERROR", "status cannot be 'deleted' on create")
        return _err("VALIDATION_ERROR", "status cannot be 'deleted' on create")

    if not authed_user:
        _log("error", "UNAUTHORIZED", "Not authenticated")
        return _err("UNAUTHORIZED", "Not authenticated")

    # Disabled users cannot mutate
    if authed_user.get("status") == "disabled":
        _log("error", "UNAUTHORIZED", "User is disabled")
        return _err("UNAUTHORIZED", "User is disabled")

    projects = _load("projects.json")
    prj = next((p for p in projects if p.get("id") == project_id), None)
    if not prj:
        _log("error", "NOT_FOUND", "Project not found")
        return _err("NOT_FOUND", "Project not found")

    # Permission: active workspace membership with role owner/admin
    memberships = _load("workspace_users.json")
    m = next((r for r in memberships
              if r.get("workspace_id") == prj.get("workspace_id")
              and r.get("user_id") == authed_user.get("id")
              and r.get("status") == "active"), None)
    if not m:
        _log("error", "UNAUTHORIZED", "No active workspace membership")
        return _err("UNAUTHORIZED", "No active workspace membership")
    if m.get("role") not in ("owner", "admin"):
        _log("error", "UNAUTHORIZED", "Insufficient permission to manage project")
        return _err("UNAUTHORIZED", "Insufficient permission to manage project")

    entities = _load("project_entities.json")
    # unique(project_id, entity_type, name) where status != 'deleted'
    for e in entities:
        if e.get("project_id") == project_id and e.get("entity_type") == "state" and e.get("status") != "deleted":
            if (e.get("name") or "").strip().lower() == name.lower():
                _log("error", "CONFLICT", "A state with this name already exists")
                return _err("CONFLICT", "A state with this name already exists")

    # If creating default, unset previous default for this project/entity_type
    if is_default:
        for e in entities:
            if e.get("project_id") == project_id and e.get("entity_type") == "state" and e.get("status") != "deleted":
                if e.get("is_default") is True:
                    e["is_default"] = False
                    e["updated_at"] = _now
                    e["updated_by_user_id"] = authed_user.get("id")

    # generate id
    def _rand4():
        return "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(4))
    def _new_id(prefix):
        # try a few times to avoid collision
        for _ in range(50):
            candidate = f"{prefix}{_rand4()}{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S%f')}"
            if not any(r.get("id") == candidate for r in entities):
                return candidate
        return f"{prefix}{_rand4()}{datetime.datetime.utcnow().strftime('%y%m%d%H%M%S%f')}"

    new_ent = {
        "id": _new_id("pln_ent_"),
        "project_id": project_id,
        "entity_type": "state",
        "name": name,
        "description": description if description is not None else None,
        "status": status,
        "sort_order": sort_order if sort_order is not None else None,
        "color": color if color is not None else None,
        "state_category": state_category,
        "is_default": bool(is_default),
        "cycle_start_at": None,
        "cycle_end_at": None,
        "module_lead_user_id": None,
        "created_at": _now,
        "updated_at": _now,
        "created_by_user_id": authed_user.get("id"),
        "updated_by_user_id": authed_user.get("id"),
    }

    entities.append(new_ent)
    _save("project_entities.json", entities)

    # If project.default_state_id is null, set it to the newly created default state (or first state)
    if prj.get("default_state_id") in (None, "") and new_ent.get("status") != "deleted":
        prj["default_state_id"] = new_ent["id"] if new_ent.get("is_default") else prj.get("default_state_id")
        prj["updated_at"] = _now
        prj["updated_by_user_id"] = authed_user.get("id")
        _save("projects.json", projects)

    _log("ok")
    return {"data": new_ent}

def update_state(state_id, body, **_extra):
    import json, os, datetime, re, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f').upper()}"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("pln_req_"),
            "endpoint": "update_state",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Ambient auth: pick an active user; deny only if none.
    users = _load("users.json")
    authed_user = next((u for u in users if u.get("status") == "active"), None)
    if not authed_user:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated.")
    if authed_user.get("status") == "disabled":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is disabled.")

    # Validate inputs
    if not isinstance(state_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+.*$", state_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "state_id is invalid.")
    if not isinstance(body, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body is required and must be an object.")

    allowed_keys = {"name", "description", "status", "sort_order", "color", "state_category", "is_default"}
    for k in body.keys():
        if k not in allowed_keys:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body contains unsupported fields.", field=k)

    if "status" in body:
        if body["status"] not in ("active", "archived", "deleted"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported status enum.", field="status")
    if "state_category" in body and body["state_category"] is not None:
        if body["state_category"] not in ("backlog", "unstarted", "started", "completed", "cancelled"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported state_category enum.", field="state_category")
    if "name" in body and body["name"] is not None:
        if not isinstance(body["name"], str) or not (1 <= len(body["name"]) <= 200):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.", field="name")
    if "description" in body and body["description"] is not None:
        if not isinstance(body["description"], str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if "sort_order" in body and body["sort_order"] is not None:
        if not isinstance(body["sort_order"], (int, float)):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be a number.", field="sort_order")
    if "color" in body and body["color"] is not None:
        if not isinstance(body["color"], str) or not re.match(r"^#?[0-9A-Fa-f]{6}$", body["color"]):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "color must match ^#?[0-9A-Fa-f]{6}$.", field="color")
    if "is_default" in body and body["is_default"] is not None:
        if not isinstance(body["is_default"], bool):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "is_default must be boolean.", field="is_default")

    project_entities = _load("project_entities.json")
    state = next((e for e in project_entities if e.get("id") == state_id), None)
    if not state or state.get("entity_type") != "state":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "State not found.")

    project_id = state.get("project_id")
    projects = _load("projects.json")
    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Parent project not found.")

    # Permission: must be active member of owning workspace (and not removed); update requires owner/admin.
    workspace_id = project.get("workspace_id")
    workspace_users = _load("workspace_users.json")
    membership = next(
        (
            m for m in workspace_users
            if m.get("workspace_id") == workspace_id and m.get("user_id") == authed_user.get("id")
            and m.get("status") == "active" and m.get("role") in ("owner", "admin")
        ),
        None,
    )
    if not membership:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to update states for this project.")

    # Enforce lifecycle transitions
    if "status" in body and body["status"] is not None:
        cur = state.get("status")
        nxt = body["status"]
        transitions = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
        if cur not in transitions or nxt not in ("active", "archived", "deleted"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status value.")
        if nxt != cur and nxt not in transitions[cur]:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition state from {cur} to {nxt}.")

    # Entity-type-specific required fields
    # For entity_type='state': state_category required and is_default must not be null.
    effective_state_category = body["state_category"] if "state_category" in body else state.get("state_category")
    effective_is_default = body["is_default"] if "is_default" in body else state.get("is_default")
    if effective_state_category is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "state_category is required for states.", field="state_category")
    if effective_is_default is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_default is required for states.", field="is_default")

    # Uniqueness: unique(project_id, entity_type, name) where status != 'deleted'
    if "name" in body and body["name"] is not None:
        new_name = body["name"]
        for e in project_entities:
            if e.get("id") != state_id and e.get("project_id") == project_id and e.get("entity_type") == "state":
                if e.get("status") != "deleted" and e.get("name") == new_name:
                    _log("error", error_code="CONFLICT")
                    return _err("CONFLICT", "A state with this name already exists in the project.")

    # Soft-delete constraint: cannot delete if referenced by any issue.state_id
    if "status" in body and body["status"] == "deleted" and state.get("status") != "deleted":
        issues = _load("issues.json")
        for iss in issues:
            if iss.get("project_id") == project_id and iss.get("status") != "deleted" and iss.get("state_id") == state_id:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "State is referenced by existing issues and cannot be deleted.")

    # Apply updates
    changed = False
    for k in allowed_keys:
        if k in body:
            state[k] = body[k]
            changed = True

    if not changed:
        # No effect -> treat as success only if idempotent? Contract says no success without effect for mutation.
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No fields to update.")

    # Exactly one default per project for states: if setting true, unset others in same transaction
    if "is_default" in body and body["is_default"] is True:
        for e in project_entities:
            if e.get("project_id") == project_id and e.get("entity_type") == "state" and e.get("id") != state_id:
                if e.get("status") != "deleted" and e.get("is_default") is True:
                    e["is_default"] = False
                    e["updated_at"] = _now()
                    e["updated_by_user_id"] = authed_user.get("id")

    # If setting is_default false, ensure at least one default remains among non-deleted states
    if "is_default" in body and body["is_default"] is False:
        non_deleted_states = [e for e in project_entities if e.get("project_id") == project_id and e.get("entity_type") == "state" and e.get("status") != "deleted"]
        if non_deleted_states and not any((e.get("id") != state_id and e.get("is_default") is True) for e in non_deleted_states):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Exactly one default state is required per project; cannot unset the only default.")

    state["updated_at"] = _now()
    state["updated_by_user_id"] = authed_user.get("id")

    _save("project_entities.json", project_entities)
    _log("ok")
    return {"data": state}

