    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("pln_req_"),
            "endpoint": "delete_state",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    users = _load("users.json")
    authed_user = next((u for u in users if u.get("status") == "active"), None)
    if not authed_user:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated.")
    if authed_user.get("status") == "disabled":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is disabled.")

    if not isinstance(state_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+.*$", state_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "state_id is invalid.")

    project_entities = _load("project_entities.json")
    state = next((e for e in project_entities if e.get("id") == state_id), None)
    if not state or state.get("entity_type") != "state":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "State not found.")

    project_id = state.get("project_id")
    projects = _load("projects.json")
    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Parent project not found.")

    # Permission: manage requires owner/admin membership in workspace
    workspace_id = project.get("workspace_id")
    workspace_users = _load("workspace_users.json")
    membership = next(
        (
            m for m in workspace_users
            if m.get("workspace_id") == workspace_id and m.get("user_id") == authed_user.get("id")
            and m.get("status") == "active" and m.get("role") in ("owner", "admin")
        ),
        None,
    )
    if not membership:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to delete states for this project.")

    # Soft delete: cannot delete if referenced by any non-deleted issue
    issues = _load("issues.json")
    for iss in issues:
        if iss.get("project_id") == project_id and iss.get("status") != "deleted" and iss.get("state_id") == state_id:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "State is referenced by existing issues and cannot be deleted.")

    # Idempotent: if already deleted, report success with current row? Must have effect; so return current as already deleted.
    if state.get("status") == "deleted":
        _log("ok")
        return {"data": {"id": state_id, "deleted": True, "status": "deleted"}}

    # Transition enforcement
    if state.get("status") not in ("active", "archived"):
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot delete state from status {state.get('status')}.")

    state["status"] = "deleted"
    state["updated_at"] = _now()
    state["updated_by_user_id"] = authed_user.get("id")

    _save("project_entities.json", project_entities)
    _log("ok")
    return {"data": {"id": state_id, "deleted": True, "status": "deleted"}}

