    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("pln_req_"),
            "endpoint": "list_labels",
            "status": status_s,
            "error_code": error_code,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    users = _load("users.json")
    authed_user = next((u for u in users if u.get("status") == "active"), None)
    if not authed_user:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated.")

    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+.*$", project_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is invalid.")

    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported status enum.", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "sort_order"
    if sort not in ("sort_order", "name", "created_at", "updated_at"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported sort field.", field="sort")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported order.", field="order")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    projects = _load("projects.json")
    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")

    # Access: active membership in owning workspace
    workspace_id = project.get("workspace_id")
    workspace_users = _load("workspace_users.json")
    member = next(
        (m for m in workspace_users if m.get("workspace_id") == workspace_id and m.get("user_id") == authed_user.get("id") and m.get("status") == "active"),
        None,
    )
    if not member:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to view labels for this project.")

    entities = _load("project_entities.json")
    rows = [e for e in entities if e.get("project_id") == project_id and e.get("entity_type") == "label" and e.get("status") != "deleted"]
    if status is not None:
        # For list endpoints, allow explicit status='deleted' filter; but base rule says status != 'deleted' for list_*.
        # Enforce rule: never return deleted in list_*.
        if status == "deleted":
            rows = []
        else:
            rows = [e for e in rows if e.get("status") == status]

    def _sort_key(e):
        v = e.get(sort)
        if sort in ("created_at", "updated_at"):
            return v or ""
        if sort == "name":
            return (v or "").lower()
        # sort_order: None last in asc, first in desc
        return v

    reverse = (order == "desc")
    if sort == "sort_order":
        # stable: (is_none, value, name, id)
        def k(e):
            so = e.get("sort_order")
            return (so is None, so if so is not None else 0, (e.get("name") or "").lower(), e.get("id") or "")
        rows.sort(key=k, reverse=reverse)
    else:
        rows.sort(key=lambda e: (_sort_key(e), (e.get("id") or "")), reverse=reverse)

    # Cursor: opaque base64 of last id
    start_after_id = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            start_after_id = raw.decode("utf-8")
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    if start_after_id:
        idx = next((i for i, r in enumerate(rows) if r.get("id") == start_after_id), None)
        if idx is None:
            # unknown cursor -> empty page (common behavior) rather than error? Spec says invalid cursor is validation error; unknown is effectively invalid.
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor does not match any record.")
        rows_page = rows[idx + 1: idx + 1 + limit]
        has_more = (idx + 1 + limit) < len(rows)
    else:
        rows_page = rows[:limit]
        has_more = limit < len(rows)

    next_cursor = None
    if has_more and rows_page:
        last_id = rows_page[-1].get("id")
        next_cursor = base64.urlsafe_b64encode((last_id or "").encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "data": rows_page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

