def create_label(project_id, body, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "pln_req_" + uuid.uuid4().hex[:20],
            "endpoint": "create_label",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        # Rate limit: 120 requests/minute per "workspace" (best-effort). With ambient auth, enforce globally.
        window_s = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
                if dt >= cutoff:
                    recent += 1
            except Exception:
                continue
        if recent >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        # Quota: 50k requests/day globally
        day_cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
        daily = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
                if dt >= day_cutoff:
                    daily += 1
            except Exception:
                continue
        if daily >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", error_code=lim_err["error"]["code"])
        return lim_err

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+.*$", project_id):
        e = _err("VALIDATION_ERROR", "Invalid project_id.")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(body, dict):
        e = _err("VALIDATION_ERROR", "Invalid body.")
        _log("error", error_code=e["error"]["code"])
        return e
    allowed = {"name", "description", "status", "sort_order", "color", "is_default"}
    for k in body.keys():
        if k not in allowed:
            e = _err("VALIDATION_ERROR", f"Unknown field in body: {k}.")
            _log("error", error_code=e["error"]["code"])
            return e
    if "name" not in body or not isinstance(body.get("name"), str):
        e = _err("VALIDATION_ERROR", "Field 'name' is required and must be a string.")
        _log("error", error_code=e["error"]["code"])
        return e
    name = body.get("name").strip()
    if not (1 <= len(name) <= 100):
        e = _err("VALIDATION_ERROR", "Label name length must be between 1 and 100 characters.")
        _log("error", error_code=e["error"]["code"])
        return e
    description = body.get("description", None)
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "Field 'description' must be a string.")
        _log("error", error_code=e["error"]["code"])
        return e
    status = body.get("status", "active")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            e = _err("VALIDATION_ERROR", "Invalid status.")
            _log("error", error_code=e["error"]["code"])
            return e
    sort_order = body.get("sort_order", None)
    if sort_order is not None and not isinstance(sort_order, (int, float)):
        e = _err("VALIDATION_ERROR", "Field 'sort_order' must be a number.")
        _log("error", error_code=e["error"]["code"])
        return e
    color = body.get("color", None)
    if color is not None:
        if not isinstance(color, str) or not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            e = _err("VALIDATION_ERROR", "Invalid color format.")
            _log("error", error_code=e["error"]["code"])
            return e
        if not color.startswith("#"):
            color = "#" + color
    is_default = body.get("is_default", None)
    if is_default is not None and not isinstance(is_default, bool):
        e = _err("VALIDATION_ERROR", "Field 'is_default' must be a boolean.")
        _log("error", error_code=e["error"]["code"])
        return e

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    # Ambient auth: choose any active user (must exist)
    authed_user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            authed_user = u
            break
    if not authed_user:
        e = _err("UNAUTHORIZED", "No authenticated user context available.")
        _log("error", error_code=e["error"]["code"])
        return e

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project:
        e = _err("NOT_FOUND", "Project not found.")
        _log("error", error_code=e["error"]["code"])
        return e

    # Permission: must have active workspace membership in owning workspace (and typically admin/owner for create)
    workspace_id = project.get("workspace_id")
    workspace_users = _load("workspace_users.json")
    if not isinstance(workspace_users, list):
        workspace_users = []

    membership = None
    for m in workspace_users:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") == workspace_id and m.get("user_id") == authed_user.get("id") and m.get("status") == "active":
            if m.get("role") in ("owner", "admin"):
                membership = m
                break
    if not membership:
        # Try any active user with correct role to satisfy ambient auth prerequisites
        for u in users:
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            for m in workspace_users:
                if not isinstance(m, dict):
                    continue
                if m.get("workspace_id") == workspace_id and m.get("user_id") == u.get("id") and m.get("status") == "active" and m.get("role") in ("owner", "admin"):
                    authed_user = u
                    membership = m
                    break
            if membership:
                break
    if not membership:
        e = _err("UNAUTHORIZED", "No authorized workspace membership to create labels in this project.")
        _log("error", error_code=e["error"]["code"])
        return e

    if authed_user.get("status") == "disabled":
        e = _err("UNAUTHORIZED", "User is disabled.")
        _log("error", error_code=e["error"]["code"])
        return e

    entities = _load("project_entities.json")
    if not isinstance(entities, list):
        entities = []

    # Uniqueness: unique(project_id, entity_type, name) where status != 'deleted'
    for e_row in entities:
        if not isinstance(e_row, dict):
            continue
        if e_row.get("project_id") == project_id and e_row.get("entity_type") == "label" and e_row.get("status") != "deleted":
            if isinstance(e_row.get("name"), str) and e_row.get("name").strip().lower() == name.lower():
                e = _err("CONFLICT", "A label with the same name already exists in this project.")
                _log("error", error_code=e["error"]["code"])
                return e

    new_id = "pln_ent_" + uuid.uuid4().hex[:20].upper()
    new_row = {
        "id": new_id,
        "project_id": project_id,
        "entity_type": "label",
        "name": name,
        "description": description,
        "status": status if status else "active",
        "sort_order": float(sort_order) if isinstance(sort_order, (int, float)) else None,
        "color": color,
        "state_category": None,
        "is_default": is_default,
        "cycle_start_at": None,
        "cycle_end_at": None,
        "module_lead_user_id": None,
        "created_at": _now,
        "updated_at": _now,
        "created_by_user_id": authed_user.get("id"),
        "updated_by_user_id": authed_user.get("id"),
    }

    entities.append(new_row)
    _save("project_entities.json", entities)

    _log("success")
    return {"data": new_row}

