                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
                if dt >= cutoff:
                    recent += 1
            except Exception:
                continue
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
        daily = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
                if dt >= day_cutoff:
                    daily += 1
            except Exception:
                continue
        if daily >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", error_code=lim_err["error"]["code"])
        return lim_err

    if not isinstance(label_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+.*$", label_id):
        e = _err("VALIDATION_ERROR", "Invalid label_id.")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(body, dict):
        e = _err("VALIDATION_ERROR", "Invalid body.")
        _log("error", error_code=e["error"]["code"])
        return e
    allowed = {"name", "description", "status", "sort_order", "color", "is_default"}
    for k in body.keys():
        if k not in allowed:
            e = _err("VALIDATION_ERROR", f"Unknown field in body: {k}.")
            _log("error", error_code=e["error"]["code"])
            return e

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    authed_user = next((u for u in users if isinstance(u, dict) and u.get("status") == "active"), None)
    if not authed_user:
        e = _err("UNAUTHORIZED", "No authenticated user context available.")
        _log("error", error_code=e["error"]["code"])
        return e
    if authed_user.get("status") == "disabled":
        e = _err("UNAUTHORIZED", "User is disabled.")
        _log("error", error_code=e["error"]["code"])
        return e

    entities = _load("project_entities.json")
    if not isinstance(entities, list):
        entities = []

    idx = None
    row = None
    for i, r in enumerate(entities):
        if isinstance(r, dict) and r.get("id") == label_id:
            idx = i
            row = r
            break
    if not row or row.get("entity_type") != "label":
        e = _err("NOT_FOUND", "Label not found.")
        _log("error", error_code=e["error"]["code"])
        return e

    project_id = row.get("project_id")
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project:
        e = _err("NOT_FOUND", "Owning project not found.")
        _log("error", error_code=e["error"]["code"])
        return e

    workspace_id = project.get("workspace_id")
    workspace_users = _load("workspace_users.json")
    if not isinstance(workspace_users, list):
        workspace_users = []

    membership = None
    for m in workspace_users:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") == workspace_id and m.get("user_id") == authed_user.get("id") and m.get("status") == "active":
            if m.get("role") in ("owner", "admin"):
                membership = m
                break
    if not membership:
        for u in users:
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            for m in workspace_users:
                if not isinstance(m, dict):
                    continue
                if m.get("workspace_id") == workspace_id and m.get("user_id") == u.get("id") and m.get("status") == "active" and m.get("role") in ("owner", "admin"):
                    authed_user = u
                    membership = m
                    break
            if membership:
                break
    if not membership:
        e = _err("UNAUTHORIZED", "No authorized workspace membership to update labels in this project.")
        _log("error", error_code=e["error"]["code"])
        return e

    # Validate and apply updates
    new_row = dict(row)

    if "name" in body:
        if body["name"] is None or not isinstance(body["name"], str):
            e = _err("VALIDATION_ERROR", "Field 'name' must be a string.")
            _log("error", error_code=e["error"]["code"])
            return e
        new_name = body["name"].strip()
        if not (1 <= len(new_name) <= 100):
            e = _err("VALIDATION_ERROR", "Label name length must be between 1 and 100 characters.")
            _log("error", error_code=e["error"]["code"])
            return e
        # Uniqueness check (status != deleted) within same project/entity_type
        for r in entities:
            if not isinstance(r, dict) or r.get("id") == label_id:
                continue
            if r.get("project_id") == project_id and r.get("entity_type") == "label" and r.get("status") != "deleted":
                if isinstance(r.get("name"), str) and r.get("name").strip().lower() == new_name.lower():
                    e = _err("CONFLICT", "A label with the same name already exists in this project.")
                    _log("error", error_code=e["error"]["code"])
                    return e
        new_row["name"] = new_name

    if "description" in body:
        if body["description"] is not None and not isinstance(body["description"], str):
            e = _err("VALIDATION_ERROR", "Field 'description' must be a string.")
            _log("error", error_code=e["error"]["code"])
            return e
        new_row["description"] = body["description"]

    if "sort_order" in body:
        so = body["sort_order"]
        if so is not None and not isinstance(so, (int, float)):
            e = _err("VALIDATION_ERROR", "Field 'sort_order' must be a number.")
            _log("error", error_code=e["error"]["code"])
            return e
        new_row["sort_order"] = float(so) if isinstance(so, (int, float)) else None

    if "color" in body:
        c = body["color"]
        if c is not None:
            if not isinstance(c, str) or not re.match(r"^#?[0-9A-Fa-f]{6}$", c):
                e = _err("VALIDATION_ERROR", "Invalid color format.")
                _log("error", error_code=e["error"]["code"])
                return e
            if not c.startswith("#"):
                c = "#" + c
        new_row["color"] = c

    if "is_default" in body:
        d = body["is_default"]
        if d is not None and not isinstance(d, bool):
            e = _err("VALIDATION_ERROR", "Field 'is_default' must be a boolean.")
            _log("error", error_code=e["error"]["code"])
            return e
        new_row["is_default"] = d

    if "status" in body:
        s = body["status"]
        if s is None or not isinstance(s, str) or s not in ("active", "archived", "deleted"):
            e = _err("VALIDATION_ERROR", "Invalid status.")
            _log("error", error_code=e["error"]["code"])
            return e
        old = row.get("status")
        if old == "deleted" and s != "deleted":
            e = _err("INVALID_TRANSITION", "Cannot transition a deleted label to a non-deleted status.")
            _log("error", error_code=e["error"]["code"])
            return e
        if old in ("active", "archived") and s not in ("active", "archived", "deleted"):
            e = _err("INVALID_TRANSITION", "Invalid status transition.")
            _log("error", error_code=e["error"]["code"])
            return e
        new_row["status"] = s

        # If soft-deleting via status update, enforce "disallowed if referenced by any issue"
        if s == "deleted" and old != "deleted":
            issues = _load("issues.json")
            if not isinstance(issues, list):
                issues = []
            for iss in issues:
                if not isinstance(iss, dict):
                    continue
                if iss.get("project_id") != project_id:
                    continue
                # Any reference counts, regardless of issue status (rule says disallowed if referenced by any issue)
                lid_list = iss.get("label_ids")
                if isinstance(lid_list, list) and label_id in lid_list:
                    e = _err("CONFLICT", "Label cannot be deleted because it is referenced by one or more issues.")
                    _log("error", error_code=e["error"]["code"])
                    return e

    # No-op update should still have an effect; if no fields provided, it's a validation error in real APIs
    if all(k not in body for k in allowed):
        e = _err("VALIDATION_ERROR", "No updatable fields provided.")
        _log("error", error_code=e["error"]["code"])
        return e

    new_row["updated_at"] = _now
    new_row["updated_by_user_id"] = authed_user.get("id")

    entities[idx] = new_row
    _save("project_entities.json", entities)

    _log("success")
    return {"data": new_row}

def delete_label(label_id, **_extra):
    import json, os, datetime, time, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_label"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status, principal_user_id=None, workspace_id=None, project_id=None, entity_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "entity_id": entity_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(label_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+.*$", label_id or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "label_id is malformed"})
            return _err("VALIDATION_ERROR", "label_id is malformed", label_id=label_id)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        entities = _load("project_entities.json")
        if not isinstance(entities, list): entities = []
        ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == label_id), None)
        if not ent or ent.get("entity_type") != "label":
            _log("error", principal_user_id=principal_user_id, entity_id=label_id, error={"code": "NOT_FOUND", "message": "Label not found"})
            return _err("NOT_FOUND", "Label not found", label_id=label_id)

        if ent.get("status") == "deleted":
            _log("success", principal_user_id=principal_user_id, project_id=ent.get("project_id"), entity_id=label_id)
            return {"data": {"id": label_id, "deleted": True, "status": "deleted"}}

        project_id = ent.get("project_id")
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log("error", principal_user_id=principal_user_id, project_id=project_id, entity_id=label_id, error={"code": "NOT_FOUND", "message": "Parent project not found"})
            return _err("NOT_FOUND", "Parent project not found", project_id=project_id)

        wsp_id = prj.get("workspace_id")
        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []
        membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == wsp_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
        if not membership:
            _log("error", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=label_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership for this project."})
            return _err("UNAUTHORIZED", "No active workspace membership for this project.", workspace_id=wsp_id, project_id=project_id)

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        for iss in issues:
            if not isinstance(iss, dict):
                continue
            if iss.get("status") == "deleted":
                continue
            if iss.get("project_id") != project_id:
                continue
            lbls = iss.get("label_ids")
            if isinstance(lbls, list) and label_id in lbls:
                _log("error", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=label_id, error={"code": "CONFLICT", "message": "Label is referenced by existing issues and cannot be deleted."})
                return _err("CONFLICT", "Label is referenced by existing issues and cannot be deleted.", label_id=label_id)

        now = _now()
        for e in entities:
            if isinstance(e, dict) and e.get("id") == label_id:
                e["status"] = "deleted"
                e["updated_at"] = now
                e["updated_by_user_id"] = principal_user_id
                break
        _save("project_entities.json", entities)

        _log("success", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=label_id)
        return {"data": {"id": label_id, "entity_type": "label", "status": "deleted", "deleted": True, "project_id": project_id, "updated_at": now}}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def get_user(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "pln_req_" + uuid.uuid4().hex[:20],
            "endpoint": "get_user",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now,
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
                if dt >= cutoff:
                    recent += 1
            except Exception:
                continue
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
        daily = 0
        for r in logs:
            try:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
                if dt >= day_cutoff:
                    daily += 1
            except Exception:
                continue
        if daily >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", error_code=lim_err["error"]["code"])
        return lim_err

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    # Ambient authentication: return the principal user. With no explicit credential, select the most plausible:
    # prefer last_login_at most recent among active/disabled; fallback to most recently updated.
    def _parse_dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            if isinstance(s, str):
                return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        return None

    best = None
    best_key = None
    for u in users:
        if not isinstance(u, dict):
            continue
        # any user row can be the principal; prefer active
        ll = _parse_dt(u.get("last_login_at")) or _parse_dt(u.get("updated_at")) or _parse_dt(u.get("created_at"))
        if ll is None:
            ll = datetime.datetime(1970, 1, 1)
        key = (1 if u.get("status") == "active" else 0, ll)
        if best is None or key > best_key:
            best = u
            best_key = key

    if not best:
        e = _err("UNAUTHORIZED", "No authenticated user context available.")
        _log("error", error_code=e["error"]["code"])
        return e

    _log("success")
    return {"data": best}

def get_workspace_members(workspace_id, role=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, error=None, used_user_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"pln_log_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get_workspace_members",
            "timestamp": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "actor_user_id": used_user_id,
            "workspace_id": workspace_id,
            "error": error
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v[:-1] if v.endswith("Z") else v
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^pln_wsp_[0-9A-Z]+$", workspace_id):
        _log("VALIDATION_ERROR", {"message": "Invalid workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
    if role is not None and role not in ("owner", "admin", "member", "viewer"):
        _log("VALIDATION_ERROR", {"message": "Invalid role"})
        return _err("VALIDATION_ERROR", "Invalid role", field="role")
    if status is not None and status not in ("invited", "active", "removed"):
        _log("VALIDATION_ERROR", {"message": "Invalid status"})
        return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", {"message": "Invalid limit"})
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "joined_at"):
        _log("VALIDATION_ERROR", {"message": "Invalid sort_by"})
        return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", {"message": "Invalid sort_order"})
        return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

    cur = _decode_cursor(cursor)
    if cursor is not None and cur is None:
        _log("VALIDATION_ERROR", {"message": "Invalid cursor"})
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
    if cur is not None:
        if cur.get("v") != 1 or cur.get("sort_by") != sort_by or cur.get("sort_order") != sort_order or cur.get("workspace_id") != workspace_id:
            _log("VALIDATION_ERROR", {"message": "Cursor does not match request"})
            return _err("VALIDATION_ERROR", "Cursor does not match request parameters", field="cursor")

    # Ambient auth resolution: pick any active user with an active membership in this workspace
    users = _load("users.json")
    ws = _load("workspaces.json")
    memberships = _load("workspace_users.json")
    if not isinstance(users, list): users = []
    if not isinstance(ws, list): ws = []
    if not isinstance(memberships, list): memberships = []

    workspace_row = next((w for w in ws if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if workspace_row is None:
        _log("NOT_FOUND", {"message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    actor_user_id = None
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id:
            continue
        if m.get("status") != "active":
            continue
        uid = m.get("user_id")
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
        if u and u.get("status") == "active":
            actor_user_id = uid
            break
    if actor_user_id is None:
        _log("UNAUTHORIZED", {"message": "No authenticated principal for workspace"})
        return _err("UNAUTHORIZED", "Not authenticated")

    # Rate limiting / quota (if present)
    limits = _load("rate_limits.json")
    if isinstance(limits, dict):
        per_min = limits.get("per_minute")
        per_day = limits.get("per_day")
    else:
        per_min = None
        per_day = None

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now_dt = datetime.datetime.utcnow()
    if isinstance(per_min, int) and per_min > 0:
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("actor_user_id") != actor_user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= per_min:
            _log("RATE_LIMIT", {"message": "Rate limit exceeded"}, used_user_id=actor_user_id)
            return _err("RATE_LIMIT", "Rate limit exceeded")
    if isinstance(per_day, int) and per_day > 0:
        window_start = now_dt - datetime.timedelta(days=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("actor_user_id") != actor_user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= per_day:
            _log("QUOTA_EXCEEDED", {"message": "Quota exceeded"}, used_user_id=actor_user_id)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")

    # Enforce: caller must have active membership in workspace
    caller_membership = next((m for m in memberships if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == actor_user_id and m.get("status") == "active"), None)
    if caller_membership is None:
        _log("UNAUTHORIZED", {"message": "Not a member"}, used_user_id=actor_user_id)
        return _err("UNAUTHORIZED", "Not authenticated")

    # Filter and sort
    rows = [m for m in memberships if isinstance(m, dict) and m.get("workspace_id") == workspace_id]
    if role is not None:
        rows = [m for m in rows if m.get("role") == role]
    if status is not None:
        rows = [m for m in rows if m.get("status") == status]

    def _sort_key(m):
        dt = _parse_dt(m.get(sort_by))
        # For nulls: push to end for asc, start for desc (common behavior)
        if dt is None:
            return (1, datetime.datetime.min, m.get("id") or "")
        return (0, dt, m.get("id") or "")

    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: cursor holds last seen sort value + id
    start_index = 0
    if cur is not None:
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        last_dt = _parse_dt(last_val) if isinstance(last_val, str) else None
        # find first row strictly after (or before) last tuple depending on order
        def _tuple(m):
            dt = _parse_dt(m.get(sort_by))
            null_flag = 1 if dt is None else 0
            dtv = dt if dt is not None else datetime.datetime.min
            return (null_flag, dtv, m.get("id") or "")
        last_tuple = (1, datetime.datetime.min, last_id or "")
        if last_dt is not None:
            last_tuple = (0, last_dt, last_id or "")
        # scan to position after last
        for i, m in enumerate(rows):
            if not isinstance(m, dict):
                continue
            tup = _tuple(m)
            if not reverse:
                if tup > last_tuple:
                    start_index = i
                    break
                start_index = i + 1
            else:
                if tup < last_tuple:
                    start_index = i
                    break
                start_index = i + 1

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = None
    if has_more and len(page) > 0:
        last = page[-1]
        next_cursor = _encode_cursor({
            "v": 1,
            "workspace_id": workspace_id,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "last_id": last.get("id"),
            "last_val": last.get(sort_by)
        })

    resp = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log("OK", used_user_id=actor_user_id)
    return resp

def get_projects(workspace_id, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, error=None, used_user_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
