            "id": f"pln_log_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get_projects",
            "timestamp": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "actor_user_id": used_user_id,
            "workspace_id": workspace_id,
            "error": error
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v[:-1] if v.endswith("Z") else v
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^pln_wsp_[0-9A-Z]+$", workspace_id):
        _log("VALIDATION_ERROR", {"message": "Invalid workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
    if status is not None and status not in ("active", "archived"):
        _log("VALIDATION_ERROR", {"message": "Invalid status"})
        return _err("VALIDATION_ERROR", "Invalid status", field="status")
