    if wsp is None:
        _log("NOT_FOUND", {"message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    # Ambient auth: any active user who is active member of this workspace
    actor_user_id = None
    for m in memberships:
        if not isinstance(m, dict): 
            continue
        if m.get("workspace_id") != workspace_id or m.get("status") != "active":
            continue
        uid = m.get("user_id")
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
        if u and u.get("status") == "active":
            actor_user_id = uid
            break
    if actor_user_id is None:
        _log("UNAUTHORIZED", {"message": "Not authenticated"})
        return _err("UNAUTHORIZED", "Not authenticated")

    # Rate limiting / quota (if present)
    limits = _load("rate_limits.json")
    if isinstance(limits, dict):
        per_min = limits.get("per_minute")
        per_day = limits.get("per_day")
    else:
        per_min = None
        per_day = None

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now_dt = datetime.datetime.utcnow()
    if isinstance(per_min, int) and per_min > 0:
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("actor_user_id") != actor_user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= per_min:
            _log("RATE_LIMIT", {"message": "Rate limit exceeded"}, used_user_id=actor_user_id)
            return _err("RATE_LIMIT", "Rate limit exceeded")
    if isinstance(per_day, int) and per_day > 0:
        window_start = now_dt - datetime.timedelta(days=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("actor_user_id") != actor_user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= per_day:
            _log("QUOTA_EXCEEDED", {"message": "Quota exceeded"}, used_user_id=actor_user_id)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")

    # Must have active membership in owning workspace
    caller_membership = next((m for m in memberships if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == actor_user_id and m.get("status") == "active"), None)
    if caller_membership is None:
        _log("UNAUTHORIZED", {"message": "Not a member"}, used_user_id=actor_user_id)
        return _err("UNAUTHORIZED", "Not authenticated")

    rows = [p for p in projects if isinstance(p, dict) and p.get("workspace_id") == workspace_id]
    # business rule: project.status != 'deleted' (no deleted state; treat archived)
    rows = [p for p in rows if p.get("status") in ("active", "archived")]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]

    reverse = (sort_order == "desc")

    def _sort_key(p):
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(p.get(sort_by))
            if dt is None:
                return (1, datetime.datetime.min, p.get("id") or "")
            return (0, dt, p.get("id") or "")
        val = p.get(sort_by)
        sval = val if isinstance(val, str) else ""
        # normalize case-insensitive for names/identifiers
        return (0, sval.lower(), p.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination
    start_index = 0
    if cur is not None:
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        if sort_by in ("created_at", "updated_at"):
            last_dt = _parse_dt(last_val) if isinstance(last_val, str) else None
            def _tuple(p):
                dt = _parse_dt(p.get(sort_by))
                null_flag = 1 if dt is None else 0
                dtv = dt if dt is not None else datetime.datetime.min
                return (null_flag, dtv, p.get("id") or "")
            last_tuple = (1, datetime.datetime.min, last_id or "")
            if last_dt is not None:
                last_tuple = (0, last_dt, last_id or "")
        else:
            last_s = last_val if isinstance(last_val, str) else ""
            def _tuple(p):
                sval = p.get(sort_by)
                sval = sval if isinstance(sval, str) else ""
                return (0, sval.lower(), p.get("id") or "")
            last_tuple = (0, last_s.lower(), last_id or "")

        for i, p in enumerate(rows):
            tup = _tuple(p)
            if not reverse:
                if tup > last_tuple:
                    start_index = i
                    break
                start_index = i + 1
            else:
                if tup < last_tuple:
                    start_index = i
                    break
                start_index = i + 1

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = None
    if has_more and len(page) > 0:
        last = page[-1]
        next_cursor = _encode_cursor({
            "v": 1,
            "workspace_id": workspace_id,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "last_id": last.get("id"),
            "last_val": last.get(sort_by)
        })

    resp = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log("OK", used_user_id=actor_user_id)
    return resp

def create_project(workspace_id, identifier, name, description=None, status=None, default_state_id=None, **_extra):
    import json, os, datetime, time, re, secrets
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_project"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"
    def _log(status_s, principal_user_id=None, workspace_id=None, project_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^pln_wsp_[0-9A-Z]+$", workspace_id or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "workspace_id is missing or invalid"})
            return _err("VALIDATION_ERROR", "workspace_id is missing or invalid", workspace_id=workspace_id)
        if not isinstance(identifier, str) or not re.match(r"^[A-Z][A-Z0-9]{1,9}$", identifier or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "identifier is invalid"})
            return _err("VALIDATION_ERROR", "identifier is invalid; must match ^[A-Z][A-Z0-9]{1,9}$", identifier=identifier)
        if not isinstance(name, str) or not (1 <= len(name) <= 200):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "name is invalid"})
            return _err("VALIDATION_ERROR", "name is invalid; length must be between 1 and 200", name=name)
        if description is not None and not isinstance(description, str):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "description must be a string"})
            return _err("VALIDATION_ERROR", "description must be a string", description=description)
        if status is not None and status not in ("active", "archived"):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "status is invalid"})
            return _err("VALIDATION_ERROR", "status is invalid", status=status)
        if default_state_id is not None and (not isinstance(default_state_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+$", default_state_id)):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "default_state_id is invalid"})
            return _err("VALIDATION_ERROR", "default_state_id is invalid", default_state_id=default_state_id)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list): workspaces = []
        wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not wsp:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "NOT_FOUND", "message": "Workspace not found"})
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []
        membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
        if not membership:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership."})
            return _err("UNAUTHORIZED", "No active workspace membership.", workspace_id=workspace_id)
        if membership.get("role") not in ("owner", "admin"):
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "UNAUTHORIZED", "message": "Insufficient role to create projects in this workspace (requires owner/admin)."})
            return _err("UNAUTHORIZED", "Insufficient role to create projects in this workspace (requires owner/admin).", workspace_id=workspace_id, role=membership.get("role"))

        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        if any(isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("identifier") == identifier for p in projects):
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "CONFLICT", "message": "identifier already exists in this workspace"})
            return _err("CONFLICT", "identifier already exists in this workspace", identifier=identifier, workspace_id=workspace_id)
        if any(isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("name") == name for p in projects):
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "CONFLICT", "message": "name already exists in this workspace"})
            return _err("CONFLICT", "name already exists in this workspace", name=name, workspace_id=workspace_id)

        if default_state_id is not None:
            ents = _load("project_entities.json")
            if not isinstance(ents, list): ents = []
            st = next((e for e in ents if isinstance(e, dict) and e.get("id") == default_state_id), None)
            if not st:
                _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "NOT_FOUND", "message": "default_state_id not found"})
                return _err("NOT_FOUND", "default_state_id not found", default_state_id=default_state_id)
            if st.get("entity_type") != "state":
                _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "VALIDATION_ERROR", "message": "default_state_id must reference an entity_type='state' row"})
                return _err("VALIDATION_ERROR", "default_state_id must reference an entity_type='state' row", default_state_id=default_state_id)
            if st.get("status") == "deleted":
                _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, error={"code": "CONFLICT", "message": "default_state_id cannot reference a deleted state"})
                return _err("CONFLICT", "default_state_id cannot reference a deleted state", default_state_id=default_state_id)

        now = _now()
        project_id = _gen_id("pln_prj")
        row = {
            "id": project_id,
            "workspace_id": workspace_id,
            "identifier": identifier,
            "name": name,
            "description": description,
            "status": status or "active",
            "issue_number_seq": 1,
            "default_state_id": default_state_id,
            "created_at": now,
            "updated_at": now,
            "created_by_user_id": principal_user_id,
            "updated_by_user_id": principal_user_id,
        }
        projects.append(row)
        _save("projects.json", projects)

        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id)
        return {"data": row}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

