            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+$", project_id):
        _log("VALIDATION_ERROR", {"message": "Invalid project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id", field="project_id")
    if status is not None and status not in ("active", "archived", "deleted"):
        _log("VALIDATION_ERROR", {"message": "Invalid status"})
        return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if module_lead_user_id is not None:
        if not isinstance(module_lead_user_id, str) or not re.match(r"^pln_usr_[0-9A-Z]+$", module_lead_user_id):
            _log("VALIDATION_ERROR", {"message": "Invalid module_lead_user_id"})
            return _err("VALIDATION_ERROR", "Invalid module_lead_user_id", field="module_lead_user_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", {"message": "Invalid limit"})
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")
    if sort_by is None:
        sort_by = "sort_order"
    if sort_by not in ("sort_order", "created_at", "updated_at", "name"):
        _log("VALIDATION_ERROR", {"message": "Invalid sort_by"})
        return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log("VALIDATION_ERROR", {"message": "Invalid sort_order"})
        return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

    cur = _decode_cursor(cursor)
    if cursor is not None and cur is None:
        _log("VALIDATION_ERROR", {"message": "Invalid cursor"})
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
    if cur is not None:
        if cur.get("v") != 1 or cur.get("sort_by") != sort_by or cur.get("sort_order") != sort_order or cur.get("project_id") != project_id:
            _log("VALIDATION_ERROR", {"message": "Cursor does not match request"})
            return _err("VALIDATION_ERROR", "Cursor does not match request parameters", field="cursor")

    users = _load("users.json")
    projects = _load("projects.json")
    workspaces = _load("workspaces.json")
    memberships = _load("workspace_users.json")
    entities = _load("project_entities.json")
    if not isinstance(users, list): users = []
    if not isinstance(projects, list): projects = []
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(memberships, list): memberships = []
    if not isinstance(entities, list): entities = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if prj is None:
        _log("NOT_FOUND", {"message": "Project not found"})
        return _err("NOT_FOUND", "Project not found", project_id=project_id)
    workspace_id = prj.get("workspace_id")

    # Ambient auth: must be an active user with active membership in workspace
    actor_user_id = None
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id or m.get("status") != "active":
            continue
        uid = m.get("user_id")
        u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
        if u and u.get("status") == "active":
            actor_user_id = uid
            break
    if actor_user_id is None:
        _log("UNAUTHORIZED", {"message": "Not authenticated"}, workspace_id=workspace_id)
        return _err("UNAUTHORIZED", "Not authenticated")

    # Rate limiting / quota (if present)
    limits = _load("rate_limits.json")
    if isinstance(limits, dict):
        per_min = limits.get("per_minute")
        per_day = limits.get("per_day")
    else:
        per_min = None
        per_day = None

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now_dt = datetime.datetime.utcnow()
    if isinstance(per_min, int) and per_min > 0:
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("actor_user_id") != actor_user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= per_min:
            _log("RATE_LIMIT", {"message": "Rate limit exceeded"}, used_user_id=actor_user_id, workspace_id=workspace_id)
            return _err("RATE_LIMIT", "Rate limit exceeded")
    if isinstance(per_day, int) and per_day > 0:
        window_start = now_dt - datetime.timedelta(days=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("actor_user_id") != actor_user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= per_day:
            _log("QUOTA_EXCEEDED", {"message": "Quota exceeded"}, used_user_id=actor_user_id, workspace_id=workspace_id)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")

    caller_membership = next((m for m in memberships if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == actor_user_id and m.get("status") == "active"), None)
    if caller_membership is None:
        _log("UNAUTHORIZED", {"message": "Not a member"}, used_user_id=actor_user_id, workspace_id=workspace_id)
        return _err("UNAUTHORIZED", "Not authenticated")

    rows = [e for e in entities if isinstance(e, dict) and e.get("project_id") == project_id and e.get("entity_type") == "module"]
    if status is None:
        # Default: exclude deleted for list
        rows = [e for e in rows if e.get("status") != "deleted"]
    else:
        rows = [e for e in rows if e.get("status") == status]
    if module_lead_user_id is not None:
        rows = [e for e in rows if e.get("module_lead_user_id") == module_lead_user_id]

    reverse = (sort_order == "desc")

    def _sort_key(e):
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(e.get(sort_by))
            if dt is None:
                return (1, datetime.datetime.min, e.get("id") or "")
            return (0, dt, e.get("id") or "")
        if sort_by == "sort_order":
            so = e.get("sort_order")
            # None last for asc, first for desc
            if so is None:
                # put at end for asc
                return (1, 0.0, e.get("id") or "")
            try:
                return (0, float(so), e.get("id") or "")
            except Exception:
                return (0, 0.0, e.get("id") or "")
        # name
        nm = e.get("name")
        nm = nm if isinstance(nm, str) else ""
        return (0, nm.lower(), e.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination
    start_index = 0
    if cur is not None:
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        if sort_by in ("created_at", "updated_at"):
            last_dt = _parse_dt(last_val) if isinstance(last_val, str) else None
            def _tuple(e):
                dt = _parse_dt(e.get(sort_by))
                null_flag = 1 if dt is None else 0
                dtv = dt if dt is not None else datetime.datetime.min
                return (null_flag, dtv, e.get("id") or "")
            last_tuple = (1, datetime.datetime.min, last_id or "")
            if last_dt is not None:
                last_tuple = (0, last_dt, last_id or "")
        elif sort_by == "sort_order":
            try:
                last_so = None if last_val is None else float(last_val)
            except Exception:
                last_so = None
            def _tuple(e):
                so = e.get("sort_order")
                if so is None:
                    return (1, 0.0, e.get("id") or "")
                try:
                    return (0, float(so), e.get("id") or "")
                except Exception:
                    return (0, 0.0, e.get("id") or "")
            if last_so is None:
                last_tuple = (1, 0.0, last_id or "")
            else:
                last_tuple = (0, last_so, last_id or "")
        else:
            last_s = last_val if isinstance(last_val, str) else ""
            def _tuple(e):
                nm = e.get("name")
                nm = nm if isinstance(nm, str) else ""
                return (0, nm.lower(), e.get("id") or "")
            last_tuple = (0, last_s.lower(), last_id or "")

        for i, e in enumerate(rows):
            tup = _tuple(e)
            if not reverse:
                if tup > last_tuple:
                    start_index = i
                    break
                start_index = i + 1
            else:
                if tup < last_tuple:
                    start_index = i
                    break
                start_index = i + 1

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = None
    if has_more and len(page) > 0:
        last = page[-1]
        next_cursor = _encode_cursor({
            "v": 1,
            "project_id": project_id,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "last_id": last.get("id"),
            "last_val": last.get(sort_by)
        })

    resp = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log("OK", used_user_id=actor_user_id, workspace_id=workspace_id)
    return resp

def get_module(module_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    users = _load("users.json")
    workspaces = _load("workspaces.json")
    workspace_users = _load("workspace_users.json")
    projects = _load("projects.json")
    entities = _load("project_entities.json")

    # Resolve authenticated principal (ambient)
    principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active"), None)
    if not principal:
        principal = next((u for u in users if isinstance(u, dict)), None)
    principal_id = principal.get("id") if principal else None

    # Request logging (best-effort if collection exists; otherwise noop)
    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "pln_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "get_module",
                "principal_user_id": principal_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)

    # Validate input
    if module_id is None or not isinstance(module_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+$", module_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "module_id is required and must match ^pln_ent_[0-9A-Z]+$")

    # Fetch module entity
    ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == module_id), None)
    if not ent or ent.get("entity_type") != "module":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Module not found")

    project_id = ent.get("project_id")
    if not project_id:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Module project not found")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found")

    ws_id = prj.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    # Authorization: caller must have active membership in owning workspace
    if not principal_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated user context available")
    mem = next((m for m in workspace_users
                if isinstance(m, dict)
                and m.get("workspace_id") == ws_id
                and m.get("user_id") == principal_id
                and m.get("status") == "active"), None)
    if not mem:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to view module in this workspace")

    # list_* rule says status != 'deleted' for listing; get_module tool spec doesn't, but a deleted module should be not found.
    if ent.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Module not found")

    _log("ok")
    return {"data": ent}

def create_module(project_id, name, description=None, status=None, sort_order=None, color=None, module_lead_user_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    users = _load("users.json")
    workspaces = _load("workspaces.json")
    workspace_users = _load("workspace_users.json")
    projects = _load("projects.json")
    entities = _load("project_entities.json")

    principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active"), None)
    if not principal:
        principal = next((u for u in users if isinstance(u, dict)), None)
    principal_id = principal.get("id") if principal else None

    def _log(status_s, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "pln_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "create_module",
                "principal_user_id": principal_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)

    # Validate input
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+$", project_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required and must match ^pln_prj_[0-9A-Z]+$")
    if not isinstance(name, str) or not (1 <= len(name) <= 2000):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")
    if sort_order is not None and not isinstance(sort_order, (int, float)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be a number when provided")
    if color is not None:
        if not isinstance(color, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "color must be a string when provided")
        if not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "color must match ^#?[0-9A-Fa-f]{6}$ when provided")
    if module_lead_user_id is not None:
        if not isinstance(module_lead_user_id, str) or not re.match(r"^pln_usr_[0-9A-Z]+$", module_lead_user_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "module_lead_user_id must match ^pln_usr_[0-9A-Z]+$ when provided")

    # Authn / mutating rule: disabled user cannot mutate
    if not principal_id:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated user context available")
    if principal.get("status") == "disabled":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is disabled")

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found")

    ws_id = prj.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    mem = next((m for m in workspace_users
                if isinstance(m, dict)
                and m.get("workspace_id") == ws_id
                and m.get("user_id") == principal_id
                and m.get("status") == "active"), None)
    if not mem or mem.get("role") not in ("owner", "admin"):
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to create modules in this project")

    if module_lead_user_id is not None:
        lead = next((u for u in users if isinstance(u, dict) and u.get("id") == module_lead_user_id), None)
        if not lead:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "module_lead_user_id user not found")

    # Uniqueness: unique(project_id, entity_type, name) where status != 'deleted'
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("project_id") == project_id and e.get("entity_type") == "module" and e.get("status") != "deleted" and e.get("name") == name:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "A module with this name already exists in the project")

    # Create id
    new_id = "pln_ent_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f").upper()

    rec = {
        "id": new_id,
        "project_id": project_id,
        "entity_type": "module",
        "name": name,
        "description": description,
        "status": status or "active",
        "sort_order": sort_order,
        "color": color,
        "state_category": None,
        "is_default": None,
        "cycle_start_at": None,
        "cycle_end_at": None,
        "module_lead_user_id": module_lead_user_id,
        "created_at": now,
        "updated_at": now,
        "created_by_user_id": principal_id,
        "updated_by_user_id": principal_id
    }

    entities.append(rec)
    _save("project_entities.json", entities)

    _log("ok")
    return {"data": rec}

