    ent = None
    for i, e in enumerate(entities):
        if isinstance(e, dict) and e.get("id") == module_id:
            idx = i
            ent = e
            break
    if not ent or ent.get("entity_type") != "module":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Module not found")

    project_id = ent.get("project_id")
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found")

    ws_id = prj.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
    if not ws:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    mem = next((m for m in workspace_users
                if isinstance(m, dict)
                and m.get("workspace_id") == ws_id
                and m.get("user_id") == principal_id
                and m.get("status") == "active"), None)
    if not mem or mem.get("role") not in ("owner", "admin"):
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to modify modules in this project")

    if module_lead_user_id is not None:
        lead = next((u for u in users if isinstance(u, dict) and u.get("id") == module_lead_user_id), None)
        if not lead:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "module_lead_user_id user not found")

    # If soft-deleting via update, enforce "hard delete disallowed if referenced by any issue" business rule:
    # Implement as: cannot set status='deleted' while referenced by any non-deleted issue.module_ids (audit safety).
    if status == "deleted" and ent.get("status") != "deleted":
        for iss in issues:
            if not isinstance(iss, dict):
                continue
            if iss.get("status") == "deleted":
                continue
            if iss.get("project_id") != project_id:
                continue
            mids = iss.get("module_ids") or []
            if isinstance(mids, list) and module_id in mids:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "Module cannot be deleted because it is referenced by existing issues")

    # Uniqueness constraint on (project_id, entity_type, name) where status != 'deleted'
    if name is not None:
        for e in entities:
            if not isinstance(e, dict):
                continue
            if e.get("id") == module_id:
                continue
            if e.get("project_id") == project_id and e.get("entity_type") == "module" and e.get("status") != "deleted" and e.get("name") == name:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "A module with this name already exists in the project")

    # Apply updates
    updated = dict(ent)
    if name is not None:
        updated["name"] = name
    if description is not None:
        updated["description"] = description
    if sort_order is not None:
        updated["sort_order"] = sort_order
    if color is not None:
        updated["color"] = color
    if module_lead_user_id is not None or module_lead_user_id is None and ("module_lead_user_id" in ({} if module_lead_user_id is None else {"x":1})):
        # Only set when provided; leaving as-is otherwise.
        pass
    if module_lead_user_id is not None:
        updated["module_lead_user_id"] = module_lead_user_id
    if is_default is not None:
        updated["is_default"] = is_default

    # Lifecycle transitions for project_entities.status
    if status is not None and status != ent.get("status"):
        allowed = {
            "active": ("archived", "deleted"),
            "archived": ("active", "deleted"),
            "deleted": ()
        }
        cur = ent.get("status")
        if cur not in allowed or status not in allowed[cur]:
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}")
        updated["status"] = status

    updated["updated_at"] = now
    updated["updated_by_user_id"] = principal_id

    entities[idx] = updated
    _save("project_entities.json", entities)

    _log("ok")
    return {"data": updated}

def delete_module(module_id, **_extra):
    import json, os, datetime, time, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_module"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status, principal_user_id=None, workspace_id=None, project_id=None, entity_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "entity_id": entity_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(module_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+$", module_id or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "module_id is missing or malformed"})
            return _err("VALIDATION_ERROR", "module_id is missing or malformed", module_id=module_id)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        entities = _load("project_entities.json")
        if not isinstance(entities, list): entities = []
        ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == module_id), None)
        if not ent or ent.get("entity_type") != "module":
            _log("error", principal_user_id=principal_user_id, entity_id=module_id, error={"code": "NOT_FOUND", "message": "Module not found"})
            return _err("NOT_FOUND", "Module not found", module_id=module_id)

        if ent.get("status") == "deleted":
            _log("success", principal_user_id=principal_user_id, project_id=ent.get("project_id"), entity_id=module_id)
            return {"data": {"id": module_id, "deleted": True, "status": "deleted"}}

        project_id = ent.get("project_id")
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log("error", principal_user_id=principal_user_id, project_id=project_id, entity_id=module_id, error={"code": "NOT_FOUND", "message": "Parent project not found"})
            return _err("NOT_FOUND", "Parent project not found", project_id=project_id)

        wsp_id = prj.get("workspace_id")
        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []
        membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == wsp_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
        if not membership:
            _log("error", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=module_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership for this project."})
            return _err("UNAUTHORIZED", "No active workspace membership for this project.", workspace_id=wsp_id, project_id=project_id)

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        for iss in issues:
            if not isinstance(iss, dict):
                continue
            if iss.get("status") == "deleted":
                continue
            if iss.get("project_id") != project_id:
                continue
            mids = iss.get("module_ids")
            if isinstance(mids, list) and module_id in mids:
                _log("error", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=module_id, error={"code": "CONFLICT", "message": "Module is referenced by existing issues and cannot be deleted."})
                return _err("CONFLICT", "Module is referenced by existing issues and cannot be deleted.", module_id=module_id)

        now = _now()
        for e in entities:
            if isinstance(e, dict) and e.get("id") == module_id:
                e["status"] = "deleted"
                e["updated_at"] = now
                e["updated_by_user_id"] = principal_user_id
                break
        _save("project_entities.json", entities)

        _log("success", principal_user_id=principal_user_id, workspace_id=wsp_id, project_id=project_id, entity_id=module_id)
        return {"data": {"id": module_id, "entity_type": "module", "status": "deleted", "deleted": True, "project_id": project_id, "updated_at": now}}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def list_module_issues(project_id, module_id, status=None, state_id=None, issue_type_id=None, priority=None, assignee_user_id=None, label_id=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers ----
    def _parse_ts(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _cursor_encode(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                return obj
        except Exception:
            return None
        return None

    def _record_call(status_code, credential_user_id, workspace_id, project_id_in):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"pln_req_{int(time.time()*1000)}",
                "tool": "list_module_issues",
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "user_id": credential_user_id,
                "workspace_id": workspace_id,
                "project_id": project_id_in,
            }
        )
        _save("request_logs.json", logs)

    # ---- validate inputs ----
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+$", project_id):
        resp = _err("VALIDATION_ERROR", "project_id is malformed.")
        _record_call("VALIDATION_ERROR", None, None, project_id if isinstance(project_id, str) else None)
        return resp
    if not isinstance(module_id, str) or not re.match(r"^pln_ent_[0-9A-Z]+$", module_id):
        resp = _err("VALIDATION_ERROR", "module_id is malformed.")
        _record_call("VALIDATION_ERROR", None, None, project_id)
        return resp

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            resp = _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")
            _record_call("VALIDATION_ERROR", None, None, project_id)
            return resp
    if priority is not None:
        if not isinstance(priority, str) or priority not in ("low", "medium", "high", "urgent"):
            resp = _err("VALIDATION_ERROR", "priority must be one of: low, medium, high, urgent.")
            _record_call("VALIDATION_ERROR", None, None, project_id)
            return resp

    for nm, val, pat in (
        ("state_id", state_id, r"^pln_ent_[0-9A-Z]+$"),
        ("issue_type_id", issue_type_id, r"^pln_ent_[0-9A-Z]+$"),
        ("label_id", label_id, r"^pln_ent_[0-9A-Z]+$"),
    ):
        if val is not None and (not isinstance(val, str) or not re.match(pat, val)):
            resp = _err("VALIDATION_ERROR", f"{nm} is malformed.")
            _record_call("VALIDATION_ERROR", None, None, project_id)
            return resp

    if assignee_user_id is not None and (not isinstance(assignee_user_id, str) or not re.match(r"^pln_usr_[0-9A-Z]+$", assignee_user_id)):
        resp = _err("VALIDATION_ERROR", "assignee_user_id is malformed.")
        _record_call("VALIDATION_ERROR", None, None, project_id)
        return resp

    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "issue_number", "priority", "title"):
        resp = _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, issue_number, priority, title.")
        _record_call("VALIDATION_ERROR", None, None, project_id)
        return resp

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        resp = _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
        _record_call("VALIDATION_ERROR", None, None, project_id)
        return resp

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _record_call("VALIDATION_ERROR", None, None, project_id)
        return resp

    cur = _cursor_decode(cursor)
    if cursor is not None and cur is None:
        resp = _err("VALIDATION_ERROR", "cursor is invalid.")
        _record_call("VALIDATION_ERROR", None, None, project_id)
        return resp
    if cur is not None:
        if cur.get("tool") != "list_module_issues" or cur.get("project_id") != project_id or cur.get("module_id") != module_id:
            resp = _err("VALIDATION_ERROR", "cursor does not match this request context.")
            _record_call("VALIDATION_ERROR", None, None, project_id)
            return resp

    # ---- ambient auth: pick any active user with active membership in workspace owning this project ----
    users = _load("users.json")
    workspaces = _load("workspaces.json")
    ws_users = _load("workspace_users.json")
    projects = _load("projects.json")
    ents = _load("project_entities.json")
    issues = _load("issues.json")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        resp = _err("NOT_FOUND", "Project not found.")
        _record_call("NOT_FOUND", None, None, project_id)
        return resp

    workspace_id = proj.get("workspace_id")
    w = next((x for x in workspaces if isinstance(x, dict) and x.get("id") == workspace_id), None)
    if not w:
        resp = _err("NOT_FOUND", "Workspace for project not found.")
        _record_call("NOT_FOUND", None, None, project_id)
        return resp

    # Must have active membership (any role) in workspace to read
    active_memberships = [m for m in ws_users if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("status") == "active"]
    active_user_ids = {m.get("user_id") for m in active_memberships if isinstance(m.get("user_id"), str)}
    principal = next((u for u in users if isinstance(u, dict) and u.get("id") in active_user_ids and u.get("status") == "active"), None)
    if not principal:
        resp = _err("UNAUTHORIZED", "No authorized principal for this workspace.")
        _record_call("UNAUTHORIZED", None, workspace_id, project_id)
        return resp

    # Validate module exists and belongs to project and entity_type module
    module = next((e for e in ents if isinstance(e, dict) and e.get("id") == module_id), None)
    if not module or module.get("project_id") != project_id or module.get("entity_type") != "module" or module.get("status") == "deleted":
        resp = _err("NOT_FOUND", "Module not found in project.")
        _record_call("NOT_FOUND", principal.get("id"), workspace_id, project_id)
        return resp

    # ---- filtering ----
    filtered = []
    for iss in issues:
        if not isinstance(iss, dict):
            continue
        if iss.get("project_id") != project_id:
            continue
        if iss.get("status") == "deleted":
            continue
        mids = iss.get("module_ids")
        if not isinstance(mids, list) or module_id not in mids:
            continue
        if status is not None and iss.get("status") != status:
            continue
        if state_id is not None and iss.get("state_id") != state_id:
            continue
        if issue_type_id is not None and iss.get("issue_type_id") != issue_type_id:
            continue
        if priority is not None and iss.get("priority") != priority:
            continue
        if assignee_user_id is not None:
            au = iss.get("assignee_user_ids")
            if not isinstance(au, list) or assignee_user_id not in au:
                continue
        if label_id is not None:
            lids = iss.get("label_ids")
            if not isinstance(lids, list) or label_id not in lids:
                continue
        filtered.append(iss)

    total = len(filtered)

    def _priority_rank(p):
        # for sorting stable; None last in asc, first in desc
        m = {"low": 1, "medium": 2, "high": 3, "urgent": 4}
        return m.get(p, 10)

    def _sort_key(iss):
        if sort in ("created_at", "updated_at"):
            ts = _parse_ts(iss.get(sort))
            # None -> minimal for asc, maximal for desc; handle later with tuple
            return ts
        if sort == "issue_number":
            return iss.get("issue_number")
        if sort == "priority":
            return _priority_rank(iss.get("priority"))
        if sort == "title":
            return (iss.get("title") or "")
        return iss.get("updated_at")

    # deterministic tie-breakers
    reverse = (order == "desc")

    def _composite_key(iss):
        primary = _sort_key(iss)
        # normalize primary for None cases
        if sort in ("created_at", "updated_at"):
            if primary is None:
                primary = datetime.datetime.min if not reverse else datetime.datetime.max
        elif sort == "issue_number":
            if not isinstance(primary, int):
                primary = -1 if not reverse else 10**18
        elif sort == "priority":
            if not isinstance(primary, int):
                primary = 10
        elif sort == "title":
            if not isinstance(primary, str):
                primary = ""
        return (primary, iss.get("id") or "")

    filtered.sort(key=_composite_key, reverse=reverse)

    # ---- pagination ----
    start = 0
    if cur is not None:
        start = cur.get("offset")
        if not isinstance(start, int) or start < 0:
            resp = _err("VALIDATION_ERROR", "cursor offset is invalid.")
            _record_call("VALIDATION_ERROR", principal.get("id"), workspace_id, project_id)
            return resp

    page = filtered[start : start + limit]
    next_cursor = None
    has_more = start + limit < len(filtered)
    if has_more:
        next_cursor = _cursor_encode(
            {"tool": "list_module_issues", "project_id": project_id, "module_id": module_id, "offset": start + limit}
        )

    resp = {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    _record_call("OK", principal.get("id"), workspace_id, project_id)
    return resp

