            return _err("UNAUTHORIZED", "No active workspace membership for this project.", workspace_id=workspace_id, project_id=project_id)

        entities = _load("project_entities.json")
        if not isinstance(entities, list): entities = []
        mod = next((e for e in entities if isinstance(e, dict) and e.get("id") == module_id), None)
        if not mod or mod.get("entity_type") != "module" or mod.get("project_id") != project_id:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, module_id=module_id, error={"code": "NOT_FOUND", "message": "Module not found in project"})
            return _err("NOT_FOUND", "Module not found in project", module_id=module_id, project_id=project_id)
        if mod.get("status") == "deleted":
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, module_id=module_id, error={"code": "CONFLICT", "message": "Module is deleted"})
            return _err("CONFLICT", "Module is deleted", module_id=module_id)

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        issue_map = {i.get("id"): i for i in issues if isinstance(i, dict) and isinstance(i.get("id"), str)}
        missing = [iid for iid in issue_ids if iid not in issue_map]
        if missing:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, module_id=module_id, error={"code": "NOT_FOUND", "message": "One or more issues not found", "missing_issue_ids": missing})
            return _err("NOT_FOUND", "One or more issues not found", missing_issue_ids=missing)
        wrong_project = [iid for iid in issue_ids if issue_map[iid].get("project_id") != project_id]
        if wrong_project:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, module_id=module_id, error={"code": "VALIDATION_ERROR", "message": "All issues must belong to the provided project_id", "issue_ids": wrong_project})
            return _err("VALIDATION_ERROR", "All issues must belong to the provided project_id", issue_ids=wrong_project)

        now = _now()
        changed = 0
        updated_issue_ids = []
        for iid in issue_ids:
            iss = issue_map[iid]
            mids = iss.get("module_ids")
            if not isinstance(mids, list):
                mids = []
                iss["module_ids"] = mids
            if module_id not in mids:
                mids.append(module_id)
                iss["updated_at"] = now
                iss["updated_by_user_id"] = principal_user_id
                changed += 1
            updated_issue_ids.append(iid)

        if changed == 0:
            _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, module_id=module_id)
            return {"data": {"project_id": project_id, "module_id": module_id, "issue_ids": updated_issue_ids, "changed": 0, "idempotent": True}}

        _save("issues.json", issues)
        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, module_id=module_id)
        return {"data": {"project_id": project_id, "module_id": module_id, "issue_ids": updated_issue_ids, "changed": changed}}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
