def get_issue_comments(project_id, issue_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _mk_cursor(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _auth_context_for_project(prj_id):
        users = _load("users.json")
        wsu = _load("workspace_users.json")
        workspaces = _load("workspaces.json")
        projects = _load("projects.json")

        prj = next((p for p in projects if p.get("id") == prj_id), None)
        if not prj:
            return None, None, None, None

        ws_id = prj.get("workspace_id")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return prj, None, None, None

        active_users = {u["id"]: u for u in users if u.get("status") == "active"}
        candidates = []
        for m in wsu:
            if m.get("workspace_id") == ws_id and m.get("status") == "active":
                uid = m.get("user_id")
                if uid in active_users:
                    candidates.append((m, active_users[uid]))
        if not candidates:
            return prj, ws, None, None

        candidates.sort(key=lambda t: (0 if t[0].get("role") == "owner" else 1, t[0].get("created_at") or ""))
        m, u = candidates[0]
        return prj, ws, m, u

    def _log(endpoint, status, principal_user_id=None, workspace_id=None, project_id=None, meta=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        if started_at is None:
            started_at = time.time()
        latency_ms = int(max(0, (time.time() - started_at) * 1000))
        row = {
            "id": "pln_req_" + hashlib.sha256(f"{endpoint}|{now}|{os.getpid()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "status": status,
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+$", project_id):
        _log("get_issue_comments", "error", meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "project_id is malformed.")
    if not isinstance(issue_id, str) or not re.match(r"^pln_iss_[0-9A-Z]+$", issue_id):
        _log("get_issue_comments", "error", meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "issue_id is malformed.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("get_issue_comments", "error", meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    else:
        limit = 50
    if cursor is not None and not isinstance(cursor, str):
        _log("get_issue_comments", "error", meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    prj, ws, membership, principal = _auth_context_for_project(project_id)
    if not prj or not ws:
        _log("get_issue_comments", "error", project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Project not found.")
    if not membership:
        _log("get_issue_comments", "error", workspace_id=ws.get("id"), project_id=project_id, meta={"code": "UNAUTHORIZED"}, started_at=started)
        return _err("UNAUTHORIZED", "Not authorized to view this project's issues/comments.")

    issues = _load("issues.json")
    issue = next((i for i in issues if i.get("id") == issue_id), None)
    if not issue or issue.get("project_id") != project_id:
        _log(
            "get_issue_comments",
            "error",
            principal_user_id=principal.get("id") if principal else None,
            workspace_id=ws.get("id"),
            project_id=project_id,
            meta={"code": "NOT_FOUND"},
            started_at=started,
        )
        return _err("NOT_FOUND", "Issue not found in the specified project.")

    comments = issue.get("comments") if isinstance(issue.get("comments"), list) else []
    comments_sorted = sorted(comments, key=lambda c: (c.get("created_at") or "", c.get("id") or ""))

    cur_obj = _parse_cursor(cursor)
    if cursor is not None and cur_obj is None:
        _log(
            "get_issue_comments",
            "error",
            principal_user_id=principal.get("id") if principal else None,
            workspace_id=ws.get("id"),
            project_id=project_id,
            meta={"code": "VALIDATION_ERROR"},
            started_at=started,
        )
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    start_idx = 0
    if cur_obj:
        if cur_obj.get("issue_id") != issue_id or cur_obj.get("project_id") != project_id:
            _log(
                "get_issue_comments",
                "error",
                principal_user_id=principal.get("id") if principal else None,
                workspace_id=ws.get("id"),
                project_id=project_id,
                meta={"code": "VALIDATION_ERROR"},
                started_at=started,
            )
            return _err("VALIDATION_ERROR", "cursor does not match the requested resource.")
        after = cur_obj.get("after")  # last comment id
        if after is not None and not isinstance(after, str):
            _log(
                "get_issue_comments",
                "error",
                principal_user_id=principal.get("id") if principal else None,
                workspace_id=ws.get("id"),
                project_id=project_id,
                meta={"code": "VALIDATION_ERROR"},
                started_at=started,
            )
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        if after:
            for idx, c in enumerate(comments_sorted):
                if c.get("id") == after:
                    start_idx = idx + 1
                    break
            else:
                # If the cursor points to a non-existent comment (deleted from history), treat as invalid.
                _log(
                    "get_issue_comments",
                    "error",
                    principal_user_id=principal.get("id") if principal else None,
                    workspace_id=ws.get("id"),
                    project_id=project_id,
                    meta={"code": "VALIDATION_ERROR"},
                    started_at=started,
                )
                return _err("VALIDATION_ERROR", "cursor is invalid or expired.")

    page = comments_sorted[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(comments_sorted)
    next_cursor = None
    if has_more and page:
        next_cursor = _mk_cursor({"project_id": project_id, "issue_id": issue_id, "after": page[-1].get("id")})

    resp = {
        "data": page,
        "meta": {
            "total": len(comments_sorted),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

    _log(
        "get_issue_comments",
        "ok",
        principal_user_id=principal.get("id") if principal else None,
        workspace_id=ws.get("id"),
        project_id=project_id,
        meta={"issue_id": issue_id, "count": len(page)},
        started_at=started,
    )
    return resp

