            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, issue_id=issue_id, error={"code": "NOT_FOUND", "message": "Issue not found in project"})
            return _err("NOT_FOUND", "Issue not found in project", issue_id=issue_id, project_id=project_id)

        comments = issue.get("comments")
        if not isinstance(comments, list):
            comments = []
            issue["comments"] = comments

        now = _now()
        cid = _gen_id("pln_cmt")
        existing_ids = {c.get("id") for c in comments if isinstance(c, dict)}
        while cid in existing_ids:
            cid = _gen_id("pln_cmt")

        comment = {
            "id": cid,
            "body": body.get("body"),
            "created_by_user_id": principal_user_id,
            "created_at": now,
            "updated_at": now,
            "status": "active",
        }
        comments.append(comment)
        issue["updated_at"] = now
        issue["updated_by_user_id"] = principal_user_id

        _save("issues.json", issues)
        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, issue_id=issue_id)
        return {"data": comment}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def create_issue(project_id, body, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _auth_context_for_project(prj_id):
        users = _load("users.json")
        wsu = _load("workspace_users.json")
        workspaces = _load("workspaces.json")
        projects = _load("projects.json")

        prj = next((p for p in projects if p.get("id") == prj_id), None)
        if not prj:
            return None, None, None, None

        ws_id = prj.get("workspace_id")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return prj, None, None, None

        active_users = {u["id"]: u for u in users if u.get("status") == "active"}
        candidates = []
        for m in wsu:
            if m.get("workspace_id") == ws_id and m.get("status") == "active":
                uid = m.get("user_id")
                if uid in active_users:
                    candidates.append((m, active_users[uid]))
        if not candidates:
            return prj, ws, None, None

        candidates.sort(key=lambda t: (0 if t[0].get("role") == "owner" else 1, t[0].get("created_at") or ""))
        m, u = candidates[0]
        return prj, ws, m, u

    def _log(endpoint, status, principal_user_id=None, workspace_id=None, project_id=None, meta=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        if started_at is None:
            started_at = time.time()
        latency_ms = int(max(0, (time.time() - started_at) * 1000))
        row = {
            "id": "pln_req_" + hashlib.sha256(f"{endpoint}|{now}|{os.getpid()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "status": status,
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^pln_prj_[0-9A-Z]+$", project_id):
        _log("create_issue", "error", meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "project_id is malformed.")
    if not isinstance(body, dict):
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "body must be an object.")
    allowed_keys = {"title", "description", "state_id", "issue_type_id", "priority", "assignee_user_ids", "label_ids", "module_ids", "cycle_ids", "status"}
    for k in body.keys():
        if k not in allowed_keys:
            _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", f"Unexpected field in body: {k}")
    if "title" not in body:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "title is required.")
    if not isinstance(body.get("title"), str) or not (1 <= len(body.get("title")) <= 500):
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "title length must be between 1 and 500 characters.")
    if "description" in body and body["description"] is not None and not isinstance(body["description"], str):
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "description must be a string when provided.")

    priority = body.get("priority")
    if priority is not None and priority not in {"low", "medium", "high", "urgent"}:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "priority must be one of low, medium, high, urgent.")

    status = body.get("status", "active")
    if status not in {"active", "archived", "deleted"}:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted.")

    def _validate_id(field, val, pattern):
        if val is None:
            return True, None
        if not isinstance(val, str) or not re.match(pattern, val):
            return False, f"{field} is malformed."
        return True, None

    ok, msg = _validate_id("state_id", body.get("state_id"), r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg = _validate_id("issue_type_id", body.get("issue_type_id"), r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)

    def _validate_id_list(field, val, pattern):
        if val is None:
            return True, None, []
        if not isinstance(val, list):
            return False, f"{field} must be an array.", None
        out = []
        for x in val:
            if not isinstance(x, str) or not re.match(pattern, x):
                return False, f"{field} contains a malformed id.", None
            out.append(x)
        return True, None, out

    ok, msg, assignees = _validate_id_list("assignee_user_ids", body.get("assignee_user_ids"), r"^pln_usr_[0-9A-Z]+$")
    if not ok:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg, label_ids = _validate_id_list("label_ids", body.get("label_ids"), r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg, module_ids = _validate_id_list("module_ids", body.get("module_ids"), r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg, cycle_ids = _validate_id_list("cycle_ids", body.get("cycle_ids"), r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("create_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)

    prj, ws, membership, principal = _auth_context_for_project(project_id)
    if not prj or not ws:
        _log("create_issue", "error", project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Project not found.")
    if not membership or not principal:
        _log("create_issue", "error", workspace_id=ws.get("id") if ws else None, project_id=project_id, meta={"code": "UNAUTHORIZED"}, started_at=started)
        return _err("UNAUTHORIZED", "Not authorized to create issues in this project.")
    if principal.get("status") == "disabled":
        _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "UNAUTHORIZED"}, started_at=started)
        return _err("UNAUTHORIZED", "User is disabled.")

    # Cross-reference validation (project_entities)
    ents = _load("project_entities.json")
    ents_by_id = {e.get("id"): e for e in ents if isinstance(e, dict)}

    def _must_entity(ent_id, entity_type):
        e = ents_by_id.get(ent_id)
        if not e:
            return None, f"{entity_type} entity not found."
        if e.get("project_id") != project_id or e.get("entity_type") != entity_type:
            return None, f"{entity_type} entity does not belong to this project."
        if e.get("status") == "deleted":
            return None, f"{entity_type} entity is deleted."
        return e, None

    if body.get("state_id") is not None:
        _, emsg = _must_entity(body.get("state_id"), "state")
        if emsg:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", emsg)
    if body.get("issue_type_id") is not None:
        _, emsg = _must_entity(body.get("issue_type_id"), "issue_type")
        if emsg:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", emsg)

    for lid in label_ids:
        _, emsg = _must_entity(lid, "label")
        if emsg:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "label_ids contains an invalid label for this project.")
    for mid in module_ids:
        _, emsg = _must_entity(mid, "module")
        if emsg:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "module_ids contains an invalid module for this project.")
    for cid in cycle_ids:
        _, emsg = _must_entity(cid, "cycle")
        if emsg:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "cycle_ids contains an invalid cycle for this project.")

    # Validate assignees against active membership in workspace
    wsu = _load("workspace_users.json")
    active_member_user_ids = {m.get("user_id") for m in wsu if m.get("workspace_id") == prj.get("workspace_id") and m.get("status") == "active"}
    for uid in assignees:
        if uid not in active_member_user_ids:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "assignee_user_ids contains a user who is not an active member of the workspace.")

    projects = _load("projects.json")
    prj_idx = next((i for i, p in enumerate(projects) if p.get("id") == project_id), None)
    if prj_idx is None:
        _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Project not found.")
    prj_row = projects[prj_idx]
    if prj_row.get("status") == "archived" and status == "active":
        # Allow creating issues in archived projects? Not specified; keep permissive and allow.
        pass

    # Apply default state when not provided
    state_id = body.get("state_id")
    if state_id is None and prj_row.get("default_state_id"):
        # default_state_id must reference a state in same project; validate
        dsid = prj_row.get("default_state_id")
        if isinstance(dsid, str) and dsid in ents_by_id:
            e = ents_by_id[dsid]
            if e.get("project_id") == project_id and e.get("entity_type") == "state" and e.get("status") != "deleted":
                state_id = dsid

    # Allocate issue number seq "atomically" for this datastore (read-modify-write)
    seq = prj_row.get("issue_number_seq")
    if not isinstance(seq, int) or seq < 1:
        _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "CONFLICT"}, started_at=started)
        return _err("CONFLICT", "Project issue number sequence is invalid.")
    issue_number = seq
    prj_row["issue_number_seq"] = seq + 1
    prj_row["updated_at"] = _now()
    prj_row["updated_by_user_id"] = principal.get("id")
    projects[prj_idx] = prj_row
    _save("projects.json", projects)

    readable_identifier = f"{prj_row.get('identifier')}-{issue_number}"

    issues = _load("issues.json")
    # Uniqueness checks
    for i in issues:
        if i.get("project_id") == project_id and i.get("issue_number") == issue_number:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "CONFLICT"}, started_at=started)
            return _err("CONFLICT", "Allocated issue number already exists (data corruption).")
        if i.get("project_id") == project_id and i.get("readable_identifier") == readable_identifier:
            _log("create_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "CONFLICT"}, started_at=started)
            return _err("CONFLICT", "Allocated readable identifier already exists (data corruption).")

    now = _now()
    iss_id = "pln_iss_" + hashlib.sha256(f"{project_id}|{readable_identifier}|{now}|{os.getpid()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper()

    issue = {
        "id": iss_id,
        "project_id": project_id,
        "issue_number": issue_number,
        "readable_identifier": readable_identifier,
        "title": body.get("title"),
        "description": body.get("description"),
        "status": status,
        "state_id": state_id,
        "issue_type_id": body.get("issue_type_id"),
        "priority": priority,
        "assignee_user_ids": assignees if assignees is not None else [],
        "label_ids": label_ids if label_ids is not None else [],
        "module_ids": module_ids if module_ids is not None else [],
        "cycle_ids": cycle_ids if cycle_ids is not None else [],
        "comments": [],
        "worklogs": [],
        "created_at": now,
        "updated_at": now,
        "created_by_user_id": principal.get("id"),
        "updated_by_user_id": principal.get("id"),
    }

    issues.append(issue)
    _save("issues.json", issues)

    _log(
        "create_issue",
        "ok",
        principal_user_id=principal.get("id"),
        workspace_id=ws.get("id"),
        project_id=project_id,
        meta={"issue_id": iss_id, "readable_identifier": readable_identifier},
        started_at=started,
    )
    return {"data": issue}

