        _log("update_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg, label_ids = _validate_optional_list("label_ids", r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("update_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg, module_ids = _validate_optional_list("module_ids", r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("update_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)
    ok, msg, cycle_ids = _validate_optional_list("cycle_ids", r"^pln_ent_[0-9A-Z]+$")
    if not ok:
        _log("update_issue", "error", project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", msg)

    prj, ws, membership, principal = _auth_context_for_project(project_id)
    if not prj or not ws:
        _log("update_issue", "error", project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Project not found.")
    if not membership or not principal:
        _log("update_issue", "error", workspace_id=ws.get("id") if ws else None, project_id=project_id, meta={"code": "UNAUTHORIZED"}, started_at=started)
        return _err("UNAUTHORIZED", "Not authorized to update issues in this project.")
    if principal.get("status") == "disabled":
        _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "UNAUTHORIZED"}, started_at=started)
        return _err("UNAUTHORIZED", "User is disabled.")

    issues = _load("issues.json")
    idx = next((i for i, it in enumerate(issues) if it.get("id") == issue_id), None)
    if idx is None:
        _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Issue not found.")
    issue = issues[idx]
    if issue.get("project_id") != project_id:
        _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Issue not found in the specified project.")

    if issue.get("status") == "deleted":
        _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "INVALID_TRANSITION"}, started_at=started)
        return _err("INVALID_TRANSITION", "Cannot update a deleted issue.")

    # Enforce lifecycle transitions for issue.status
    if "status" in body:
        old = issue.get("status")
        new = body.get("status")
        transitions = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set(),
        }
        if old != new:
            if new not in transitions.get(old, set()):
                _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "INVALID_TRANSITION"}, started_at=started)
                return _err("INVALID_TRANSITION", f"Illegal status transition from {old} to {new}.")

    # Cross-project reference validation
    ents = _load("project_entities.json")
    ents_by_id = {e.get("id"): e for e in ents if isinstance(e, dict)}

    def _validate_entity(ent_id, etype):
        e = ents_by_id.get(ent_id)
        if not e:
            return False
        return e.get("project_id") == project_id and e.get("entity_type") == etype and e.get("status") != "deleted"

    if "state_id" in body and body.get("state_id") is not None:
        if not _validate_entity(body["state_id"], "state"):
            _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "state_id is invalid for this project.")
    if "issue_type_id" in body and body.get("issue_type_id") is not None:
        if not _validate_entity(body["issue_type_id"], "issue_type"):
            _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "issue_type_id is invalid for this project.")
    if label_ids is not None:
        for lid in label_ids:
            if not _validate_entity(lid, "label"):
                _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
                return _err("VALIDATION_ERROR", "label_ids contains an invalid label for this project.")
    if module_ids is not None:
        for mid in module_ids:
            if not _validate_entity(mid, "module"):
                _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
                return _err("VALIDATION_ERROR", "module_ids contains an invalid module for this project.")
    if cycle_ids is not None:
        for cid in cycle_ids:
            if not _validate_entity(cid, "cycle"):
                _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
                return _err("VALIDATION_ERROR", "cycle_ids contains an invalid cycle for this project.")

    # Validate assignees against active membership in workspace
    if assignees is not None:
        wsu = _load("workspace_users.json")
        active_member_user_ids = {m.get("user_id") for m in wsu if m.get("workspace_id") == prj.get("workspace_id") and m.get("status") == "active"}
        for uid in assignees:
            if uid not in active_member_user_ids:
                _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "VALIDATION_ERROR"}, started_at=started)
                return _err("VALIDATION_ERROR", "assignee_user_ids contains a user who is not an active member of the workspace.")

    # Apply updates
    changed = False
    for field in ["title", "description", "state_id", "issue_type_id", "priority", "status"]:
        if field in body:
            issue[field] = body.get(field)
            changed = True

    if assignees is not None:
        issue["assignee_user_ids"] = assignees
        changed = True
    if label_ids is not None:
        issue["label_ids"] = label_ids
        changed = True
    if module_ids is not None:
        issue["module_ids"] = module_ids
        changed = True
    if cycle_ids is not None:
        issue["cycle_ids"] = cycle_ids
        changed = True

    if not changed:
        _log("update_issue", "error", principal_user_id=principal.get("id"), workspace_id=ws.get("id"), project_id=project_id, meta={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "No changes applied.")

    now = _now()
    issue["updated_at"] = now
    issue["updated_by_user_id"] = principal.get("id")
    issues[idx] = issue
    _save("issues.json", issues)

    _log(
        "update_issue",
        "ok",
        principal_user_id=principal.get("id"),
        workspace_id=ws.get("id"),
        project_id=project_id,
        meta={"issue_id": issue_id},
        started_at=started,
    )
    return {"data": issue}

def list_cycles(project_id, status=None, search=None, order_by=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "pln_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": "list_cycles",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfgs = _load("rate_limits.json")
        if not isinstance(cfgs, list):
            cfgs = []
        cfg = cfgs[0] if cfgs else {}
        rpm = cfg.get("requests_per_minute", 600)
        rpd = cfg.get("requests_per_day", 20000)
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 600
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                c_min += 1
            if ts >= day_ago:
                c_day += 1
        if c_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded (requests per minute).", limit=rpm, window_seconds=60)
        if c_day >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, window_seconds=86400)
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, extra={"error": rl["error"]["code"]})
        return rl

    # Validate inputs
    if not isinstance(project_id, str) or not project_id.strip():
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")
    if search is not None and not isinstance(search, str):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "search must be a string.")
    if order_by is not None:
        if not isinstance(order_by, str) or order_by not in ("sort_order", "name", "cycle_start_at", "cycle_end_at", "created_at", "updated_at"):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "order_by must be one of: sort_order, name, cycle_start_at, cycle_end_at, created_at, updated_at.")
    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        _log(404, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # AUTH: must have active membership in workspace; and user must not be disabled for mutations (read ok)
    users = _load("users.json")
    wsu = _load("workspace_users.json")
    if not isinstance(users, list):
        users = []
    if not isinstance(wsu, list):
        wsu = []

    workspace_id = project.get("workspace_id")
    member_rows = [m for m in wsu if m.get("workspace_id") == workspace_id and m.get("status") == "active"]
    if not member_rows:
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active workspace membership grants access to this project.", workspace_id=workspace_id)

    # pick an authenticated principal that can access (ambient auth)
    principal = None
    for m in member_rows:
        u = next((x for x in users if x.get("id") == m.get("user_id") and x.get("status") == "active"), None)
        if u:
            principal = u
            break
    if not principal:
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active user with workspace access available.")

    ents = _load("project_entities.json")
    if not isinstance(ents, list):
        ents = []

    rows = [e for e in ents if e.get("project_id") == project_id and e.get("entity_type") == "cycle"]
    # status != deleted by default
    if status is None:
        rows = [e for e in rows if e.get("status") != "deleted"]
    else:
        rows = [e for e in rows if e.get("status") == status]

    if search:
        q = search.casefold()
        rows = [e for e in rows if isinstance(e.get("name"), str) and q in e["name"].casefold()]

    # Sorting
    ob = order_by or "updated_at"
    od = order or "desc"

    def _parse_dt(v):
        if not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1])
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _key(e):
        v = e.get(ob)
        if ob in ("created_at", "updated_at", "cycle_start_at", "cycle_end_at"):
            dt = _parse_dt(v)
            # None sorts last in asc, first in desc by using extreme sentinel
            if dt is None:
                return datetime.datetime.max
            return dt
        if ob == "sort_order":
            try:
                return float(v)
            except Exception:
                return float("inf")
        if ob == "name":
            return (e.get("name") or "").casefold()
        return e.get(ob)

    reverse = (od == "desc")
    rows_sorted = sorted(rows, key=_key, reverse=reverse)

    # Cursor pagination: cursor encodes {"i": offset}
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "i" not in obj:
                raise ValueError("bad cursor")
            offset = int(obj["i"])
            if offset < 0:
                raise ValueError("bad cursor")
        except Exception:
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows_sorted)
    page = rows_sorted[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"i": offset + limit}, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")

    _log(200, extra={"project_id": project_id, "returned": len(page)})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor,
            "order_by": ob,
            "order": od
        }
    }

