        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                c_min += 1
            if ts >= day_ago:
                c_day += 1
        if c_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded (requests per minute).", limit=rpm, window_seconds=60)
        if c_day >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, window_seconds=86400)
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, extra={"error": rl["error"]["code"]})
        return rl

    # Validate inputs
    if not isinstance(project_id, str) or not project_id.strip():
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string.")
    if not isinstance(name, str) or not name.strip():
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if len(name) > 2000:
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "name is too long.")
    if description is not None and not isinstance(description, str):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description must be a string.")
    if color is not None:
        if not isinstance(color, str):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "color must be a string.")
        if not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "color must match ^#?[0-9A-Fa-f]{6}$.")
    if sort_order is not None and not isinstance(sort_order, (int, float)):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_order must be a number.")
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(field)

    try:
        start_dt = _parse_dt(cycle_start_at, "cycle_start_at")
        end_dt = _parse_dt(cycle_end_at, "cycle_end_at")
    except ValueError as ve:
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", f"{ve.args[0]} must be an ISO-8601 date-time string.")
    if (start_dt is None) != (end_dt is None):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cycle_start_at and cycle_end_at must both be null or both be non-null.")
    if start_dt is not None and not (start_dt < end_dt):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cycle_start_at must be earlier than cycle_end_at.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        _log(404, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    # AUTH: need active membership with role owner/admin; and user must be active (not disabled)
    wsu = _load("workspace_users.json")
    users = _load("users.json")
    if not isinstance(wsu, list):
        wsu = []
    if not isinstance(users, list):
        users = []

    workspace_id = project.get("workspace_id")
    allowed_memberships = [m for m in wsu if m.get("workspace_id") == workspace_id and m.get("status") == "active" and m.get("role") in ("owner", "admin")]
    if not allowed_memberships:
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Forbidden: requires owner/admin membership to manage cycles.", workspace_id=workspace_id)

    principal = None
    principal_membership = None
    for m in allowed_memberships:
        u = next((x for x in users if x.get("id") == m.get("user_id")), None)
        if u and u.get("status") == "active":
