    if principal.get("status") == "disabled":
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "User is disabled; mutations are not permitted.", user_id=principal.get("id"))

    ents = _load("project_entities.json")
    if not isinstance(ents, list):
        ents = []

    # Uniqueness: (project_id, entity_type, name) where status != deleted
    for e in ents:
        if e.get("project_id") == project_id and e.get("entity_type") == "cycle" and e.get("status") != "deleted" and (e.get("name") or "") == name:
            _log(409, extra={"error": "CONFLICT"})
            return _err("CONFLICT", "A non-deleted cycle with the same name already exists in this project.", project_id=project_id, name=name)

    new_id = "pln_ent_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
    row = {
        "id": new_id,
        "project_id": project_id,
