        "cycle_end_at": (end_dt.replace(microsecond=0).isoformat() + "Z") if end_dt else None,
        "module_lead_user_id": None,
        "created_at": now,
        "updated_at": now,
        "created_by_user_id": principal["id"],
        "updated_by_user_id": principal["id"]
    }

    ents.append(row)
    _save("project_entities.json", ents)

    _log(201, extra={"cycle_id": new_id, "project_id": project_id, "actor_user_id": principal["id"]})
    return {"data": row}

def update_cycle(cycle_id, name=None, description=None, color=None, cycle_start_at=None, cycle_end_at=None, sort_order=None, status=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_code, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "pln_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": "update_cycle",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfgs = _load("rate_limits.json")
        if not isinstance(cfgs, list):
            cfgs = []
        cfg = cfgs[0] if cfgs else {}
        rpm = cfg.get("requests_per_minute", 600)
        rpd = cfg.get("requests_per_day", 20000)
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 600
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 20000

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now0 = datetime.datetime.utcnow()
        one_min_ago = now0 - datetime.timedelta(minutes=1)
        day_ago = now0 - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= one_min_ago:
                c_min += 1
            if ts >= day_ago:
                c_day += 1
        if c_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded (requests per minute).", limit=rpm, window_seconds=60)
        if c_day >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, window_seconds=86400)
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, extra={"error": rl["error"]["code"]})
        return rl

    if not isinstance(cycle_id, str) or not cycle_id.strip():
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cycle_id must be a non-empty string.")
    if name is not None:
        if not isinstance(name, str) or not name.strip():
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
        if len(name) > 2000:
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name is too long.")
    if description is not None and not isinstance(description, str):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "description must be a string.")
    if color is not None:
        if not isinstance(color, str):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "color must be a string.")
        if not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "color must match ^#?[0-9A-Fa-f]{6}$.")
    if sort_order is not None and not isinstance(sort_order, (int, float)):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_order must be a number.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log(400, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(field)

    ents = _load("project_entities.json")
    if not isinstance(ents, list):
        ents = []

    idx = None
    cycle = None
    for i, e in enumerate(ents):
        if e.get("id") == cycle_id and e.get("entity_type") == "cycle":
            idx = i
            cycle = e
            break
    if cycle is None:
        _log(404, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Cycle not found.", cycle_id=cycle_id)

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if p.get("id") == cycle.get("project_id")), None)
    if not project:
        _log(404, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Project not found for cycle.", project_id=cycle.get("project_id"))

    # AUTH: need active membership with role owner/admin; principal must be active user (not disabled)
    wsu = _load("workspace_users.json")
    users = _load("users.json")
    if not isinstance(wsu, list):
        wsu = []
    if not isinstance(users, list):
        users = []

    workspace_id = project.get("workspace_id")
    allowed_memberships = [m for m in wsu if m.get("workspace_id") == workspace_id and m.get("status") == "active" and m.get("role") in ("owner", "admin")]
    if not allowed_memberships:
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Forbidden: requires owner/admin membership to manage cycles.", workspace_id=workspace_id)

    principal = None
    for m in allowed_memberships:
        u = next((x for x in users if x.get("id") == m.get("user_id")), None)
        if u and u.get("status") == "active":
            principal = u
            break
    if not principal:
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Forbidden: no active user available with required role.")
    if principal.get("status") == "disabled":
        _log(403, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "User is disabled; mutations are not permitted.", user_id=principal.get("id"))

    # Lifecycle transition validation for project_entities
    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set()
    }

    # Determine prospective start/end
    cur_start = cycle.get("cycle_start_at")
    cur_end = cycle.get("cycle_end_at")
    try:
        if cycle_start_at is not None:
            cur_start_dt = _parse_dt(cycle_start_at, "cycle_start_at")
        else:
            cur_start_dt = _parse_dt(cur_start, "cycle_start_at") if isinstance(cur_start, str) else None

        if cycle_end_at is not None:
            cur_end_dt = _parse_dt(cycle_end_at, "cycle_end_at")
        else:
            cur_end_dt = _parse_dt(cur_end, "cycle_end_at") if isinstance(cur_end, str) else None
    except ValueError as ve:
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", f"{ve.args[0]} must be an ISO-8601 date-time string.")

    if (cur_start_dt is None) != (cur_end_dt is None):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cycle_start_at and cycle_end_at must both be null or both be non-null.")
    if cur_start_dt is not None and not (cur_start_dt < cur_end_dt):
        _log(400, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cycle_start_at must be earlier than cycle_end_at.")

    # Name uniqueness if changed
    if name is not None and name != cycle.get("name"):
        for e in ents:
            if e.get("id") != cycle_id and e.get("project_id") == cycle.get("project_id") and e.get("entity_type") == "cycle" and e.get("status") != "deleted" and (e.get("name") or "") == name:
                _log(409, extra={"error": "CONFLICT"})
                return _err("CONFLICT", "A non-deleted cycle with the same name already exists in this project.", project_id=cycle.get("project_id"), name=name)

    # Status transition check
    if status is not None and status != cycle.get("status"):
        cur = cycle.get("status")
        if cur not in transitions or status not in transitions.get(cur, set()):
            _log(409, extra={"error": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", f"Cannot transition cycle status from {cur} to {status}.", from_status=cur, to_status=status)

    # Apply updates
    changed = False
    if name is not None:
        cycle["name"] = name
        changed = True
    if description is not None:
        cycle["description"] = description
        changed = True
    if color is not None:
        cycle["color"] = color
        changed = True
    if sort_order is not None:
        cycle["sort_order"] = float(sort_order)
        changed = True
    if cycle_start_at is not None:
        cycle["cycle_start_at"] = cur_start_dt.replace(microsecond=0).isoformat() + "Z" if cur_start_dt else None
        changed = True
    if cycle_end_at is not None:
        cycle["cycle_end_at"] = cur_end_dt.replace(microsecond=0).isoformat() + "Z" if cur_end_dt else None
        changed = True
    if status is not None:
        cycle["status"] = status
        changed = True

    if not changed:
        _log(200, extra={"cycle_id": cycle_id, "unchanged": True})
        return {"data": cycle}

    cycle["updated_at"] = now
    cycle["updated_by_user_id"] = principal["id"]
    ents[idx] = cycle
    _save("project_entities.json", ents)

    _log(200, extra={"cycle_id": cycle_id, "actor_user_id": principal["id"]})
    return {"data": cycle}

def delete_cycle(cycle_id, **_extra):
    import json, os, datetime, time, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_cycle"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status, principal_user_id=None, workspace_id=None, project_id=None, entity_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "entity_id": entity_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(cycle_id, str) or not cycle_id:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "cycle_id is missing or invalid"})
            return _err("VALIDATION_ERROR", "cycle_id is missing or invalid", cycle_id=cycle_id)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        entities = _load("project_entities.json")
        if not isinstance(entities, list): entities = []
        ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == cycle_id), None)
        if not ent or ent.get("entity_type") != "cycle":
            _log("error", principal_user_id=principal_user_id, entity_id=cycle_id, error={"code": "NOT_FOUND", "message": "Cycle not found"})
            return _err("NOT_FOUND", "Cycle not found", cycle_id=cycle_id)

        if ent.get("status") == "deleted":
            _log("success", principal_user_id=principal_user_id, project_id=ent.get("project_id"), entity_id=cycle_id)
            return {"data": {"id": cycle_id, "deleted": True, "status": "deleted"}}

        project_id = ent.get("project_id")
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log("error", principal_user_id=principal_user_id, project_id=project_id, entity_id=cycle_id, error={"code": "NOT_FOUND", "message": "Parent project not found"})
            return _err("NOT_FOUND", "Parent project not found", project_id=project_id)
        workspace_id = prj.get("workspace_id")

        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []
        membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
        if not membership:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, entity_id=cycle_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership for this project."})
            return _err("UNAUTHORIZED", "No active workspace membership for this project.", workspace_id=workspace_id, project_id=project_id)

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        for iss in issues:
            if not isinstance(iss, dict):
                continue
            if iss.get("status") == "deleted":
                continue
            if iss.get("project_id") != project_id:
                continue
            cids = iss.get("cycle_ids")
            if isinstance(cids, list) and cycle_id in cids:
                _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, entity_id=cycle_id, error={"code": "CONFLICT", "message": "Cycle is referenced by existing issues and cannot be deleted."})
                return _err("CONFLICT", "Cycle is referenced by existing issues and cannot be deleted.", cycle_id=cycle_id)

        now = _now()
        for e in entities:
            if isinstance(e, dict) and e.get("id") == cycle_id:
                e["status"] = "deleted"
                e["updated_at"] = now
                e["updated_by_user_id"] = principal_user_id
                break
        _save("project_entities.json", entities)

        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, entity_id=cycle_id)
        return {"data": {"id": cycle_id, "entity_type": "cycle", "status": "deleted", "deleted": True, "project_id": project_id, "updated_at": now}}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

