                "timestamp": _now(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _find_active_principal():
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        active = [u for u in users if isinstance(u, dict) and u.get("status") == "active"]
        if not active:
            return None
        def _ts(u):
            return u.get("last_login_at") or u.get("updated_at") or u.get("created_at") or ""
        active.sort(key=_ts, reverse=True)
        return active[0]

    def _require_membership_for_project(project_id, allowed_roles=None):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not proj:
            return None, _err("NOT_FOUND", "Project not found.", project_id=project_id)
        workspace_id = proj.get("workspace_id")

        principal = _find_active_principal()
        if not principal:
            return None, _err("UNAUTHORIZED", "No authenticated principal available.")

        wsu = _load("workspace_users.json")
        if not isinstance(wsu, list):
            wsu = []
        memberships = [
            m for m in wsu
            if isinstance(m, dict)
            and m.get("workspace_id") == workspace_id
            and m.get("user_id") == principal.get("id")
            and m.get("status") == "active"
        ]
        if not memberships:
            return None, _err("UNAUTHORIZED", "Active workspace membership required.", workspace_id=workspace_id)

        if allowed_roles is not None:
            ok = any(m.get("role") in allowed_roles for m in memberships)
            if not ok:
                return None, _err("UNAUTHORIZED", "Insufficient role for this operation.", required_roles=list(allowed_roles))
        return {"principal": principal, "project": proj}, None

    # Validate ids
    if not isinstance(from_cycle_id, str) or not from_cycle_id.strip():
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "from_cycle_id must be a non-empty string.")
    if not isinstance(to_cycle_id, str) or not to_cycle_id.strip():
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "to_cycle_id must be a non-empty string.")
    from_cycle_id = from_cycle_id.strip()
    to_cycle_id = to_cycle_id.strip()
    if from_cycle_id == to_cycle_id:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "from_cycle_id and to_cycle_id must be different.")

    if issue_ids is not None:
        if not isinstance(issue_ids, list) or any((not isinstance(i, str) or not i.strip()) for i in issue_ids):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "issue_ids must be an array of non-empty strings when provided.")
        issue_ids = [i.strip() for i in issue_ids]
        # de-dup keep order
        seen = set()
        dedup = []
        for i in issue_ids:
            if i not in seen:
                seen.add(i)
                dedup.append(i)
        issue_ids = dedup

    principal = _find_active_principal()
    if not principal:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No authenticated principal available.")
    if principal.get("status") == "disabled":
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "User is disabled.")

    ents = _load("project_entities.json")
    if not isinstance(ents, list):
        ents = []
    from_cycle = next((e for e in ents if isinstance(e, dict) and e.get("id") == from_cycle_id), None)
    to_cycle = next((e for e in ents if isinstance(e, dict) and e.get("id") == to_cycle_id), None)
    if not from_cycle or from_cycle.get("entity_type") != "cycle":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Source cycle not found.", from_cycle_id=from_cycle_id)
    if not to_cycle or to_cycle.get("entity_type") != "cycle":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Destination cycle not found.", to_cycle_id=to_cycle_id)

    if from_cycle.get("project_id") != to_cycle.get("project_id"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Source and destination cycles must belong to the same project.")

    # Permission: active membership required; transfer is a mutation -> require owner/admin
    ctx, e = _require_membership_for_project(from_cycle.get("project_id"), allowed_roles={"owner", "admin"})
    if e:
        _log("error", meta={"code": e["error"]["code"]})
        return e

    issues = _load("issues.json")
    if not isinstance(issues, list):
        issues = []

    # Determine candidate issues
    if issue_ids is None:
        candidates = [
            iss for iss in issues
            if isinstance(iss, dict)
            and iss.get("project_id") == from_cycle.get("project_id")
            and iss.get("status") != "deleted"
            and isinstance(iss.get("cycle_ids"), list)
            and from_cycle_id in iss.get("cycle_ids")
        ]
    else:
        # Validate all issue_ids exist, belong to same project, and are associated with source cycle
        id_to_issue = {iss.get("id"): iss for iss in issues if isinstance(iss, dict) and isinstance(iss.get("id"), str)}
        missing = [i for i in issue_ids if i not in id_to_issue]
        if missing:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "One or more issues were not found.", missing_issue_ids=missing)

        bad_project = [i for i in issue_ids if id_to_issue[i].get("project_id") != from_cycle.get("project_id")]
        if bad_project:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "One or more issues do not belong to the cycles' project.", issue_ids=bad_project)

        not_in_source = []
        for i in issue_ids:
            cids = id_to_issue[i].get("cycle_ids")
            if not isinstance(cids, list) or from_cycle_id not in cids:
                not_in_source.append(i)
        if not_in_source:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "One or more issues are not associated with the source cycle.", issue_ids=not_in_source)

        candidates = [id_to_issue[i] for i in issue_ids if id_to_issue[i].get("status") != "deleted"]

    if not candidates:
        # No success without effect
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No issues to transfer.", from_cycle_id=from_cycle_id)

    now = _now()
    moved_issue_ids = []
    changed = 0
    for iss in candidates:
        cids = iss.get("cycle_ids")
        if not isinstance(cids, list):
            cids = []
        before = list(cids)
        if from_cycle_id in cids:
            cids = [c for c in cids if c != from_cycle_id]
        if to_cycle_id not in cids:
            cids.append(to_cycle_id)
        # Only count if actual change
        if cids != before:
            iss["cycle_ids"] = cids
            iss["updated_at"] = now
            iss["updated_by_user_id"] = principal.get("id")
            changed += 1
            moved_issue_ids.append(iss.get("id"))

    if changed == 0:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No issues were modified by the transfer.", from_cycle_id=from_cycle_id, to_cycle_id=to_cycle_id)

    _save("issues.json", issues)
    _log("ok", meta={"from_cycle_id": from_cycle_id, "to_cycle_id": to_cycle_id, "changed": changed})

    return {
        "from_cycle_id": from_cycle_id,
        "to_cycle_id": to_cycle_id,
        "transferred_count": changed,
        "issue_ids": moved_issue_ids,
    }

def list_cycle_issues(cycle_id, status=None, state_id=None, issue_type_id=None, priority=None, assignee_user_id=None, label_id=None, search=None, order_by=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _log(status_s, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("pln_req"),
                "endpoint": "list_cycle_issues",
                "credential_id": credential_id,
                "status": status_s,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _find_active_principal():
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        active = [u for u in users if isinstance(u, dict) and u.get("status") == "active"]
        if not active:
            return None
        def _ts(u):
            return u.get("last_login_at") or u.get("updated_at") or u.get("created_at") or ""
        active.sort(key=_ts, reverse=True)
        return active[0]

    def _require_membership_for_project(project_id):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not proj:
            return None, _err("NOT_FOUND", "Project not found.", project_id=project_id)
        workspace_id = proj.get("workspace_id")

        principal = _find_active_principal()
        if not principal:
            return None, _err("UNAUTHORIZED", "No authenticated principal available.")

        wsu = _load("workspace_users.json")
        if not isinstance(wsu, list):
            wsu = []
        memberships = [
            m for m in wsu
            if isinstance(m, dict)
            and m.get("workspace_id") == workspace_id
            and m.get("user_id") == principal.get("id")
            and m.get("status") == "active"
        ]
        if not memberships:
            return None, _err("UNAUTHORIZED", "Active workspace membership required.", workspace_id=workspace_id)
        return {"principal": principal, "project": proj}, None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            raise ValueError("bad cursor")
        raw = base64.urlsafe_b64decode(cur.encode("utf-8")).decode("utf-8")
        obj = json.loads(raw)
        if not isinstance(obj, dict) or "offset" not in obj:
            raise ValueError("bad cursor")
        off = obj["offset"]
        if not isinstance(off, int) or off < 0:
            raise ValueError("bad cursor")
        return off

    def _encode_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8")

    # Validate base
    if not isinstance(cycle_id, str) or not cycle_id.strip():
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cycle_id must be a non-empty string.")
    cycle_id = cycle_id.strip()

    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=["active", "archived", "deleted"])

    if priority is not None and priority not in ("low", "medium", "high", "urgent"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid priority filter.", allowed=["low", "medium", "high", "urgent"])

    if order_by is not None and order_by not in ("created_at", "updated_at", "issue_number", "priority"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid order_by.", allowed=["created_at", "updated_at", "issue_number", "priority"])

    if order is not None and order not in ("asc", "desc"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid order.", allowed=["asc", "desc"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    if search is not None and (not isinstance(search, str) or len(search) > 5000):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "search must be a string up to 5000 chars.")

    # Resolve cycle
    ents = _load("project_entities.json")
    if not isinstance(ents, list):
        ents = []
    cycle = next((e for e in ents if isinstance(e, dict) and e.get("id") == cycle_id), None)
    if not cycle or cycle.get("entity_type") != "cycle":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Cycle not found.", cycle_id=cycle_id)

    # Membership required
    ctx, e = _require_membership_for_project(cycle.get("project_id"))
    if e:
        _log("error", meta={"code": e["error"]["code"]})
        return e

    # Validate entity-based filters (must exist, correct type, same project) when provided
    ent_by_id = {e.get("id"): e for e in ents if isinstance(e, dict) and isinstance(e.get("id"), str)}

    def _validate_entity_filter(ent_id, expected_type, field_name):
        if ent_id is None:
            return None
        if not isinstance(ent_id, str) or not ent_id.strip():
            return _err("VALIDATION_ERROR", f"{field_name} must be a non-empty string when provided.")
        ent_id2 = ent_id.strip()
        ent = ent_by_id.get(ent_id2)
        if not ent or ent.get("status") == "deleted":
            return _err("NOT_FOUND", f"Referenced {expected_type} not found.", **{field_name: ent_id2})
        if ent.get("entity_type") != expected_type:
            return _err("VALIDATION_ERROR", f"{field_name} must reference an entity of type '{expected_type}'.", **{field_name: ent_id2})
        if ent.get("project_id") != cycle.get("project_id"):
            return _err("VALIDATION_ERROR", f"{field_name} must belong to the same project.", **{field_name: ent_id2})
        return None

    for (val, typ, name) in (
        (state_id, "state", "state_id"),
        (issue_type_id, "issue_type", "issue_type_id"),
        (label_id, "label", "label_id"),
    ):
        verr = _validate_entity_filter(val, typ, name)
        if verr:
            _log("error", meta={"code": verr["error"]["code"]})
            return verr

    if assignee_user_id is not None and (not isinstance(assignee_user_id, str) or not assignee_user_id.strip()):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "assignee_user_id must be a non-empty string when provided.")

    # Cursor
    try:
        offset = _decode_cursor(cursor)
    except ValueError:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if offset is None:
        offset = 0

    issues = _load("issues.json")
    if not isinstance(issues, list):
        issues = []

    proj_id = cycle.get("project_id")
    q = []
    s_lc = (search or "").lower() if isinstance(search, str) else None

    for iss in issues:
        if not isinstance(iss, dict):
            continue
        if iss.get("project_id") != proj_id:
            continue
        if iss.get("status") == "deleted":
            continue
        cids = iss.get("cycle_ids")
        if not isinstance(cids, list) or cycle_id not in cids:
            continue

        if status is not None and iss.get("status") != status:
            continue
        if state_id is not None and iss.get("state_id") != state_id.strip():
            continue
        if issue_type_id is not None and iss.get("issue_type_id") != issue_type_id.strip():
            continue
        if priority is not None and iss.get("priority") != priority:
            continue
        if assignee_user_id is not None:
            au = assignee_user_id.strip()
            aul = iss.get("assignee_user_ids")
            if not isinstance(aul, list) or au not in aul:
                continue
        if label_id is not None:
            lid = label_id.strip()
            lids = iss.get("label_ids")
            if not isinstance(lids, list) or lid not in lids:
                continue
        if s_lc is not None and s_lc:
            t = (iss.get("title") or "")
            rid = (iss.get("readable_identifier") or "")
            if not (isinstance(t, str) and isinstance(rid, str)):
                pass
            if s_lc not in str(t).lower() and s_lc not in str(rid).lower():
                continue
        q.append(iss)

    # Sorting
    if order_by is None:
        order_by = "created_at"
    if order is None:
        order = "desc"
    reverse = (order == "desc")

    def _prio_rank(p):
        # low < medium < high < urgent, null last in asc
        ranks = {"low": 1, "medium": 2, "high": 3, "urgent": 4}
        if p is None:
            return 999
        return ranks.get(p, 998)

    if order_by == "priority":
        q.sort(key=lambda x: (_prio_rank(x.get("priority")), x.get("created_at") or "", x.get("id") or ""), reverse=reverse)
    elif order_by == "issue_number":
        q.sort(key=lambda x: (x.get("issue_number") if isinstance(x.get("issue_number"), int) else 10**18, x.get("id") or ""), reverse=reverse)
    else:
        q.sort(key=lambda x: (x.get(order_by) or "", x.get("id") or ""), reverse=reverse)

    total = len(q)
    page = q[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _log("ok", meta={"cycle_id": cycle_id, "returned": len(page), "total": total})

    return {
        "issues": page,
        "cycle_id": cycle_id,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
    }

def add_cycle_issues(cycle_id, issue_ids, **_extra):
    import json, os, datetime, time, re
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "add_cycle_issues"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status, principal_user_id=None, workspace_id=None, project_id=None, cycle_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "cycle_id": cycle_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(cycle_id, str) or not cycle_id.startswith("pln_ent_"):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "cycle_id is invalid"})
            return _err("VALIDATION_ERROR", "cycle_id is invalid", cycle_id=cycle_id)
        if not isinstance(issue_ids, list) or len(issue_ids) < 1:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "issue_ids must be a non-empty array"})
            return _err("VALIDATION_ERROR", "issue_ids must be a non-empty array", issue_ids=issue_ids)
        for iid in issue_ids:
            if not isinstance(iid, str) or not re.match(r"^pln_iss_[0-9A-Z]+$", iid):
                _log("error", error={"code": "VALIDATION_ERROR", "message": "One or more issue_ids are invalid", "issue_id": iid})
                return _err("VALIDATION_ERROR", "One or more issue_ids are invalid", issue_id=iid)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        entities = _load("project_entities.json")
        if not isinstance(entities, list): entities = []
        cyc = next((e for e in entities if isinstance(e, dict) and e.get("id") == cycle_id), None)
        if not cyc or cyc.get("entity_type") != "cycle":
            _log("error", principal_user_id=principal_user_id, cycle_id=cycle_id, error={"code": "NOT_FOUND", "message": "Cycle not found"})
            return _err("NOT_FOUND", "Cycle not found", cycle_id=cycle_id)
        if cyc.get("status") == "deleted":
            _log("error", principal_user_id=principal_user_id, project_id=cyc.get("project_id"), cycle_id=cycle_id, error={"code": "CONFLICT", "message": "Cycle is deleted"})
            return _err("CONFLICT", "Cycle is deleted", cycle_id=cycle_id)

        project_id = cyc.get("project_id")
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not prj:
            _log("error", principal_user_id=principal_user_id, project_id=project_id, cycle_id=cycle_id, error={"code": "NOT_FOUND", "message": "Parent project not found"})
            return _err("NOT_FOUND", "Parent project not found", project_id=project_id)
        workspace_id = prj.get("workspace_id")

        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []
        membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
        if not membership:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, cycle_id=cycle_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership for this project."})
            return _err("UNAUTHORIZED", "No active workspace membership for this project.", workspace_id=workspace_id, project_id=project_id)

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        issue_map = {i.get("id"): i for i in issues if isinstance(i, dict) and isinstance(i.get("id"), str)}
        missing = [iid for iid in issue_ids if iid not in issue_map]
        if missing:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, cycle_id=cycle_id, error={"code": "NOT_FOUND", "message": "One or more issues not found", "missing_issue_ids": missing})
            return _err("NOT_FOUND", "One or more issues not found", missing_issue_ids=missing)
        wrong_project = [iid for iid in issue_ids if issue_map[iid].get("project_id") != project_id]
        if wrong_project:
            _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, cycle_id=cycle_id, error={"code": "VALIDATION_ERROR", "message": "All issues must belong to the cycle's project", "issue_ids": wrong_project})
            return _err("VALIDATION_ERROR", "All issues must belong to the cycle's project", issue_ids=wrong_project)

        now = _now()
        changed = 0
        for iid in issue_ids:
            iss = issue_map[iid]
            cids = iss.get("cycle_ids")
            if not isinstance(cids, list):
                cids = []
                iss["cycle_ids"] = cids
            if cycle_id not in cids:
                cids.append(cycle_id)
                iss["updated_at"] = now
                iss["updated_by_user_id"] = principal_user_id
                changed += 1

        if changed > 0:
            _save("issues.json", issues)

        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, cycle_id=cycle_id)
