    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, workspace_id=None, project_id=None, meta=None, error=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"pln_log_{''.join(random.choice('0123456789ABCDEFGHJKMNPQRSTVWXYZ') for _ in range(16))}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "credential_id": credential_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "meta": meta or {},
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        rl = _load("rate_limits.json")
        qt = _load("quotas.json")
        logs = _load("request_logs.json")

        for r in rl:
            if not isinstance(r, dict): 
                continue
            if r.get("endpoint") not in (None, "*", endpoint):
                continue
            try:
                window = int(r.get("window_seconds"))
                maxr = int(r.get("max_requests"))
            except Exception:
                continue
            cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window)).replace(microsecond=0).isoformat() + "Z"
            cnt = 0
            for e in logs:
                if not isinstance(e, dict): 
                    continue
                if e.get("endpoint") != endpoint:
                    continue
                ts = e.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    cnt += 1
            if cnt >= maxr:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        for q in qt:
            if not isinstance(q, dict):
                continue
            if q.get("endpoint") not in (None, "*", endpoint):
                continue
            period = q.get("period")
            try:
                maxr = int(q.get("max_requests"))
            except Exception:
                continue
            nowdt = datetime.datetime.utcnow()
            if period == "day":
                start = nowdt.replace(hour=0, minute=0, second=0, microsecond=0)
            elif period == "month":
                start = nowdt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            else:
                continue
            cutoff = start.isoformat() + "Z"
            cnt = 0
            for e in logs:
                if not isinstance(e, dict):
                    continue
                if e.get("endpoint") != endpoint:
                    continue
                ts = e.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    cnt += 1
            if cnt >= maxr:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    endpoint = "get_issue_worklogs"
    limit_err = _enforce_limits(endpoint)
    if limit_err:
        _log(endpoint, "error", error=limit_err["error"])
        return limit_err

    if not isinstance(issue_id, str) or not re.match(r"^pln_iss_[0-9A-HJKMNP-TV-Z]{10,}$", issue_id):
        e = _err("VALIDATION_ERROR", "issue_id is malformed", field="issue_id")
        _log(endpoint, "error", error=e["error"])
        return e

    users = _load("users.json")
    memberships = _load("workspace_users.json")
    projects = _load("projects.json")
    workspaces = _load("workspaces.json")
    issues = _load("issues.json")

    authed_user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            authed_user = u
            break
    if not authed_user:
        e = _err("UNAUTHORIZED", "No authenticated user context available")
        _log(endpoint, "error", error=e["error"])
        return e

    issue = None
    for iss in issues:
        if isinstance(iss, dict) and iss.get("id") == issue_id:
            issue = iss
            break
    if not issue or issue.get("status") == "deleted":
        e = _err("NOT_FOUND", "Issue not found")
        _log(endpoint, "error", error=e["error"])
        return e

    project = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == issue.get("project_id"):
            project = p
            break
    if not project:
        e = _err("NOT_FOUND", "Project not found for issue")
        _log(endpoint, "error", project_id=issue.get("project_id"), error=e["error"])
        return e

    workspace_id = project.get("workspace_id")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if not ws:
        e = _err("NOT_FOUND", "Workspace not found for issue")
        _log(endpoint, "error", workspace_id=workspace_id, project_id=project.get("id"), error=e["error"])
        return e

    has_access = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") == workspace_id and m.get("user_id") == authed_user.get("id") and m.get("status") == "active":
            has_access = True
            break
    if not has_access:
        e = _err("UNAUTHORIZED", "Access denied to workspace/project")
        _log(endpoint, "error", workspace_id=workspace_id, project_id=project.get("id"), error=e["error"])
        return e

    worklogs = issue.get("worklogs")
    if not isinstance(worklogs, list):
        worklogs = []

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            x = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    # order by logged_at desc, else created_at desc; id as tiebreaker
    def _key(w):
        lad = _parse_dt(w.get("logged_at"))
        cad = _parse_dt(w.get("created_at"))
        # Use epoch-like comparable tuple (None treated as very old)
        base = lad or cad or datetime.datetime(1970, 1, 1)
        return (base, str(w.get("id", "")))

    ordered = sorted([w for w in worklogs if isinstance(w, dict)], key=_key, reverse=True)

    _log(endpoint, "ok", workspace_id=workspace_id, project_id=project.get("id"), meta={"count": len(ordered)})
    return {
        "issue_id": issue_id,
        "worklogs": ordered,
        "count": len(ordered)
    }

