def create_worklog(issue_id, body, **_extra):
    import json, os, datetime, time, re, secrets
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_worklog"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"
    def _parse_iso_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
    def _log(status, principal_user_id=None, workspace_id=None, project_id=None, issue_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "project_id": project_id,
            "issue_id": issue_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(issue_id, str) or not re.match(r"^pln_iss_[0-9A-HJKMNP-TV-Z]{10,}$", issue_id or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "issue_id is malformed"})
            return _err("VALIDATION_ERROR", "issue_id is malformed", issue_id=issue_id)
        if not isinstance(body, dict) or "time_spent_minutes" not in body:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "body.time_spent_minutes is required"})
            return _err("VALIDATION_ERROR", "body.time_spent_minutes is required", body=body)

        tsm = body.get("time_spent_minutes")
        if not isinstance(tsm, int) or not (1 <= tsm <= 24 * 60):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "time_spent_minutes must be an integer between 1 and 1440"})
            return _err("VALIDATION_ERROR", "time_spent_minutes must be an integer between 1 and 1440", time_spent_minutes=tsm)

        desc = body.get("description")
        if desc is not None and not isinstance(desc, str):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "description must be a string"})
            return _err("VALIDATION_ERROR", "description must be a string", description=desc)

        logged_at = body.get("logged_at")
        parsed = _parse_iso_dt(logged_at) if logged_at is not None else None
        if logged_at is not None and parsed is None:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "logged_at must be a valid ISO-8601 datetime"})
            return _err("VALIDATION_ERROR", "logged_at must be a valid ISO-8601 datetime", logged_at=logged_at)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str)), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        issues = _load("issues.json")
        if not isinstance(issues, list): issues = []
        issue = next((i for i in issues if isinstance(i, dict) and i.get("id") == issue_id), None)
        if not issue:
            _log("error", principal_user_id=principal_user_id, issue_id=issue_id, error={"code": "NOT_FOUND", "message": "Issue not found"})
            return _err("NOT_FOUND", "Issue not found", issue_id=issue_id)

        project_id = issue.get("project_id")
        projects = _load("projects.json")
        if not isinstance(projects, list): projects = []
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        workspace_id = prj.get("workspace_id") if prj else None

        if prj:
            wsus = _load("workspace_users.json")
            if not isinstance(wsus, list): wsus = []
            membership = next((m for m in wsus if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("user_id") == principal_user_id and m.get("status") == "active"), None)
            if not membership:
                _log("error", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, issue_id=issue_id, error={"code": "UNAUTHORIZED", "message": "No active workspace membership for this issue's workspace."})
                return _err("UNAUTHORIZED", "No active workspace membership for this issue's workspace.", workspace_id=workspace_id, project_id=project_id)

        worklogs = issue.get("worklogs")
        if not isinstance(worklogs, list):
            worklogs = []
            issue["worklogs"] = worklogs

        now = _now()
        wid = _gen_id("pln_wlg")
        existing_ids = {w.get("id") for w in worklogs if isinstance(w, dict)}
        while wid in existing_ids:
            wid = _gen_id("pln_wlg")

        wl = {
            "id": wid,
            "user_id": principal_user_id,
            "time_spent_minutes": tsm,
            "description": desc,
            "logged_at": logged_at,
            "created_at": now,
            "updated_at": now,
            "status": "active",
        }
        worklogs.append(wl)
        issue["updated_at"] = now
        issue["updated_by_user_id"] = principal_user_id

        _save("issues.json", issues)
        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id, project_id=project_id, issue_id=issue_id)
        return {"data": wl}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def update_worklog(worklog_id, body, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept trailing Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_sort_key(v):
        d = _parse_dt(v)
        if d is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d.astimezone(datetime.timezone.utc)

    def _b62(n):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        if n == 0:
            return "0"
        out = []
        while n:
            n, r = divmod(n, 62)
            out.append(alphabet[r])
        return "".join(reversed(out))

    def _gen_id(prefix):
        # reasonably unique offline id: prefix + base32-ish
        ts = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(6), "big")
        raw = (ts << 48) | rnd
        # use our own alphabet subset by encoding in base62 then map to vendor-like
        s = _b62(raw)
        # map to Plane-like alphabet (no 0/1/I/O etc) by base32 crockford-ish selection
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # fold base62 string bytes into crockford chars
        acc = 0
        for ch in s.encode("utf-8"):
            acc = (acc * 131 + ch) & ((1 << 64) - 1)
        out = []
        x = raw ^ acc
        for _ in range(16):
            x, r = divmod(x, 32)
            out.append(crock[r])
            if x == 0 and len(out) >= 10:
                break
        token = "".join(reversed(out))
        if len(token) < 10:
            token = (crock[0] * (10 - len(token))) + token
        return f"{prefix}{token}"

    def _log(endpoint, status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("pln_req_"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "latency_ms": None,
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- validate inputs
    if not isinstance(worklog_id, str) or not re.match(r"^pln_wlg_[0-9A-HJKMNP-TV-Z]{10,}$", worklog_id):
        _log("update_worklog", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "worklog_id is malformed", field="worklog_id")

    if not isinstance(body, dict):
        _log("update_worklog", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be an object", field="body")

    allowed = {"time_spent_minutes", "description", "logged_at"}
    for k in body.keys():
        if k not in allowed:
            _log("update_worklog", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body contains unsupported field", field=k)

    if "time_spent_minutes" in body:
        tsm = body["time_spent_minutes"]
        if not isinstance(tsm, int) or tsm < 1 or tsm > 24 * 60:
            _log("update_worklog", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "time_spent_minutes must be an integer between 1 and 1440", field="time_spent_minutes")

    if "description" in body and body["description"] is not None and not isinstance(body["description"], str):
        _log("update_worklog", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string", field="description")

    if "logged_at" in body:
        if body["logged_at"] is not None:
            dt = _parse_dt(body["logged_at"])
            if dt is None:
                _log("update_worklog", "error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "logged_at must be an ISO 8601 date-time string", field="logged_at")

    # ---- ambient auth: pick an active user
    users = _load("users.json")
    if not isinstance(users, list) or len(users) == 0:
        _log("update_worklog", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated")

    authed_user = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            authed_user = u
            break
    if authed_user is None:
        _log("update_worklog", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authenticated")

    if authed_user.get("status") == "disabled":
        _log("update_worklog", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User disabled")

    issues = _load("issues.json")
    if not isinstance(issues, list):
        issues = []

    workspace_users = _load("workspace_users.json")
    if not isinstance(workspace_users, list):
        workspace_users = []

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Find worklog embedded in some issue, then enforce permission: must be active workspace membership for the owning workspace
    found = None
    found_issue = None
    found_worklog_idx = None

    for iss in issues:
        if not isinstance(iss, dict):
            continue
        wls = iss.get("worklogs")
        if not isinstance(wls, list):
            continue
        for i, wl in enumerate(wls):
            if isinstance(wl, dict) and wl.get("id") == worklog_id:
                found = wl
                found_issue = iss
                found_worklog_idx = i
                break
        if found is not None:
            break

    if found is None:
        _log("update_worklog", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Worklog not found", worklog_id=worklog_id)

    # Permission: user must be active member of workspace owning the project for the issue
    project_id = found_issue.get("project_id")
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if proj is None:
        _log("update_worklog", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Project not found for worklog", project_id=project_id)

    workspace_id = proj.get("workspace_id")
    member_ok = False
    for wu in workspace_users:
        if (
            isinstance(wu, dict)
            and wu.get("workspace_id") == workspace_id
            and wu.get("user_id") == authed_user.get("id")
            and wu.get("status") == "active"
        ):
            member_ok = True
            break
    if not member_ok:
        _log("update_worklog", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have permission to edit this worklog")

    # Apply updates (only provided fields)
    wl = dict(found)
    if wl.get("status") == "deleted":
        # treat as not found for editing
        _log("update_worklog", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Worklog not found", worklog_id=worklog_id)

    for k in allowed:
        if k in body:
            wl[k] = body[k]

    # validate again embedded rule
    if "time_spent_minutes" in wl:
        tsm = wl.get("time_spent_minutes")
        if not isinstance(tsm, int) or tsm < 1 or tsm > 24 * 60:
            _log("update_worklog", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "time_spent_minutes must be an integer between 1 and 1440", field="time_spent_minutes")

    if wl.get("logged_at") is not None and _parse_dt(wl.get("logged_at")) is None:
        _log("update_worklog", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "logged_at must be an ISO 8601 date-time string", field="logged_at")

    wl["updated_at"] = _now_iso()

    # persist back into issue, bump issue updated_at/updated_by_user_id
    found_issue["worklogs"][found_worklog_idx] = wl
    found_issue["updated_at"] = _now_iso()
    found_issue["updated_by_user_id"] = authed_user.get("id")

    _save("issues.json", issues)
    _log("update_worklog", "ok")

    return {"data": wl}

