        rows.append(ws)

    # sort
    reverse = (sort_order == "desc")
    if sort_by in ("updated_at", "created_at"):
        rows.sort(key=lambda r: (_dt_sort_key(r.get(sort_by)), r.get("id") or ""), reverse=reverse)
    else:
        rows.sort(key=lambda r: ((r.get("name") or "").lower(), r.get("id") or ""), reverse=reverse)

    # cursor: base64url of integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("list_workspaces", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            if not raw.startswith("o:"):
                raise ValueError("bad cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("list_workspaces", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("list_workspaces", "ok")
    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def create_workspace(slug, name, **_extra):
    import json, os, datetime, time, re, secrets
    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_workspace"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"
    def _log(status, principal_user_id=None, workspace_id=None, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"pln_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
            "principal_user_id": principal_user_id,
            "workspace_id": workspace_id,
            "error": error,
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(slug, str) or not re.match(r"^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$", slug or ""):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "slug is missing or invalid"})
            return _err("VALIDATION_ERROR", "slug is missing or invalid", slug=slug)
        if not isinstance(name, str) or not (1 <= len(name) <= 200):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "name is missing or invalid"})
            return _err("VALIDATION_ERROR", "name is missing or invalid", name=name)

        users = _load("users.json")
        if not isinstance(users, list): users = []
        principal = next((u for u in users if isinstance(u, dict) and isinstance(u.get("id"), str) and u.get("status") in ("active", "disabled")), None)
        if not principal:
            _log("error", error={"code": "UNAUTHORIZED", "message": "Not authenticated"})
            return _err("UNAUTHORIZED", "Not authenticated")
        principal_user_id = principal.get("id")

        if principal.get("status") == "disabled":
            _log("error", principal_user_id=principal_user_id, error={"code": "UNAUTHORIZED", "message": "User is disabled"})
            return _err("UNAUTHORIZED", "User is disabled")

        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list): workspaces = []
        if any(isinstance(w, dict) and w.get("slug") == slug for w in workspaces):
            _log("error", principal_user_id=principal_user_id, error={"code": "CONFLICT", "message": "slug is already in use"})
            return _err("CONFLICT", "slug is already in use", slug=slug)

        wsus = _load("workspace_users.json")
        if not isinstance(wsus, list): wsus = []

        now = _now()
        workspace_id = _gen_id("pln_wsp")
        wrow = {
            "id": workspace_id,
            "slug": slug,
            "name": name,
            "owner_user_id": principal_user_id,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "created_by_user_id": principal_user_id,
            "updated_by_user_id": principal_user_id,
        }
        workspaces.append(wrow)

        # membership: enforce at most one active owner (new workspace => none exists)
        membership_id = _gen_id("pln_wsu")
        mrow = {
            "id": membership_id,
            "workspace_id": workspace_id,
            "user_id": principal_user_id,
            "role": "owner",
            "status": "active",
            "invited_by_user_id": None,
            "joined_at": now,
            "created_at": now,
            "updated_at": now,
        }
        wsus.append(mrow)

        _save("workspaces.json", workspaces)
        _save("workspace_users.json", wsus)

        _log("success", principal_user_id=principal_user_id, workspace_id=workspace_id)
        return {"data": {"workspace": wrow, "membership": mrow}}
    except Exception as e:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unexpected error", "detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def list_projects(workspace_id=None, status=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0420000" if __import__("os").path.isdir("./environment_mix/0420000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            # not expected; treat as invalid/unknown
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _latency_ms(t0):
        return int((time.time() - t0) * 1000)

    def _ensure_request_log():
        # Best-effort schema discovery; service may or may not have this file pre-created.
        # If absent, create a minimal one.
        name = "request_logs.json"
        path = os.path.join(_DB, name)
        if not os.path.exists(path):
            try:
                _save(name, [])
            except Exception:
                # If we cannot create, we still must not raise.
                return None
        return name

    def _log_request(endpoint, status_code, credential_id=None, workspace_id_used=None, meta=None, t0=None):
        fname = _ensure_request_log()
        if not fname:
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "pln_req_" + hashlib.sha1((endpoint + "|" + _now_iso() + "|" + os.urandom(6).hex()).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "status": status_code,
            "credential_id": credential_id,
            "workspace_id": workspace_id_used,
            "latency_ms": _latency_ms(t0) if t0 is not None else None,
            "created_at": _now_iso(),
            "meta": meta or {},
        }
        logs.append(row)
        try:
            _save(fname, logs)
        except Exception:
            return

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        if obj.get("v") != 1 or "pos" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        if not isinstance(obj["pos"], int) or obj["pos"] < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        # Validate it matches sort settings to prevent weird paging issues
        for k in ("sort_by", "sort_order", "workspace_id", "status", "search"):
            if k in obj and obj[k] is not None and not isinstance(obj[k], str):
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        return obj

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "list_projects"
    used_workspace_id = workspace_id

    # ---------- Validate inputs ----------
    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "workspace_id_type"}, t0=t0)
            return _err("VALIDATION_ERROR", "workspace_id must be a string.")
        if not re.match(r"^pln_wsp_[0-9A-Z]{4}.*$", workspace_id):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "workspace_id_pattern"}, t0=t0)
            return _err("VALIDATION_ERROR", "workspace_id is invalid.")
    if status is not None:
        if status not in ("active", "archived"):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "status_enum"}, t0=t0)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived.")
    if search is not None and not isinstance(search, str):
        _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "search_type"}, t0=t0)
        return _err("VALIDATION_ERROR", "search must be a string.")
    if sort_by is not None:
        if sort_by not in ("updated_at", "created_at", "name", "identifier"):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "sort_by_enum"}, t0=t0)
            return _err("VALIDATION_ERROR", "sort_by must be one of: updated_at, created_at, name, identifier.")
    if sort_order is not None:
        if sort_order not in ("asc", "desc"):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "sort_order_enum"}, t0=t0)
            return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc.")
    if limit is not None:
        if not isinstance(limit, int):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "limit_type"}, t0=t0)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "limit_range"}, t0=t0)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    else:
        limit = 50

    cur_obj = None
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if isinstance(cur_obj, dict) and "error" in cur_obj:
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "cursor_invalid"}, t0=t0)
            return cur_obj

    # Default sorting
    sort_by_eff = sort_by or "updated_at"
    sort_order_eff = sort_order or "desc"

    # Cursor must match query parameters if provided (opaque but stable)
    if cur_obj is not None:
        if (cur_obj.get("sort_by") or "updated_at") != sort_by_eff or (cur_obj.get("sort_order") or "desc") != sort_order_eff:
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "cursor_mismatch_sort"}, t0=t0)
            return _err("VALIDATION_ERROR", "cursor does not match requested sort parameters.")
        if (cur_obj.get("workspace_id") or None) != (workspace_id or None):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "cursor_mismatch_workspace"}, t0=t0)
            return _err("VALIDATION_ERROR", "cursor does not match requested workspace_id.")
        if (cur_obj.get("status") or None) != (status or None):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "cursor_mismatch_status"}, t0=t0)
            return _err("VALIDATION_ERROR", "cursor does not match requested status filter.")
        if (cur_obj.get("search") or None) != (search or None):
            _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "cursor_mismatch_search"}, t0=t0)
            return _err("VALIDATION_ERROR", "cursor does not match requested search filter.")

    # ---------- Resolve authenticated principal + membership ----------
    users = _load("users.json")
    workspace_users = _load("workspace_users.json")
    workspaces = _load("workspaces.json")
    projects = _load("projects.json")

    # Find any active user with at least one active membership (and matching workspace if scoped)
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}
    user_by_id = {u.get("id"): u for u in users if isinstance(u, dict) and u.get("id")}

    active_memberships = []
    for m in workspace_users:
        if not isinstance(m, dict):
            continue
        if m.get("status") != "active":
            continue
        wid = m.get("workspace_id")
        uid = m.get("user_id")
        if not wid or not uid:
            continue
        if workspace_id is not None and wid != workspace_id:
            continue
        u = user_by_id.get(uid)
        if not u or u.get("status") != "active":
            continue
        w = ws_by_id.get(wid)
        if not w:
            continue
        # workspace itself can be archived; still should be visible? Tool says filter by workspace_id/status/search.
        # Visibility is based on membership; keep it visible even if workspace archived, unless workspace filter invalid.
        active_memberships.append(m)

    if not active_memberships:
        _log_request(endpoint, 401, workspace_id_used=used_workspace_id, meta={"error": "no_active_membership"}, t0=t0)
        return _err("UNAUTHORIZED", "Not authenticated or no active workspace membership available for this request.")

    visible_workspace_ids = {m["workspace_id"] for m in active_memberships}

    # If a workspace_id filter is provided, validate it exists (as per tool description "workspace_id is invalid")
    if workspace_id is not None:
        if workspace_id not in ws_by_id:
            _log_request(endpoint, 404, workspace_id_used=used_workspace_id, meta={"error": "workspace_not_found"}, t0=t0)
            return _err("NOT_FOUND", "workspace_id was not found.")

    # ---------- Filter visible projects ----------
    q = []
    s_term = (search or "").strip().lower()
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("workspace_id") not in visible_workspace_ids:
            continue
        if workspace_id is not None and p.get("workspace_id") != workspace_id:
            continue
        # "project.status != 'deleted' (no deleted state stored; use archived)."
        p_status = p.get("status")
        if p_status not in ("active", "archived"):
            continue
        if status is not None and p_status != status:
            continue
        if s_term:
            hay = " ".join([
                str(p.get("identifier") or ""),
                str(p.get("name") or ""),
                str(p.get("description") or ""),
            ]).lower()
            if s_term not in hay:
                continue
        q.append(p)

    # ---------- Sort ----------
    reverse = (sort_order_eff == "desc")

    def _sort_key(p):
        if sort_by_eff in ("updated_at", "created_at"):
            dt = _parse_dt(p.get(sort_by_eff))
            # unknown dates sort last for desc, first for asc:
            if dt is None:
                dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if reverse else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            # tie-breakers: name, id
            return (dt, (p.get("name") or "").lower(), (p.get("identifier") or "").lower(), p.get("id") or "")
        if sort_by_eff == "name":
            return ((p.get("name") or "").lower(), (p.get("identifier") or "").lower(), _parse_dt(p.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), p.get("id") or "")
        if sort_by_eff == "identifier":
            return ((p.get("identifier") or "").lower(), (p.get("name") or "").lower(), _parse_dt(p.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), p.get("id") or "")
        return (p.get("id") or "")

    try:
        q.sort(key=_sort_key, reverse=reverse)
    except Exception:
        _log_request(endpoint, 500, workspace_id_used=used_workspace_id, meta={"error": "sort_failed"}, t0=t0)
        return _err("CONFLICT", "Unable to sort projects due to invalid data.")

    # ---------- Pagination ----------
    start_pos = 0
    if cur_obj is not None:
        start_pos = cur_obj.get("pos", 0)

    if start_pos > len(q):
        _log_request(endpoint, 400, workspace_id_used=used_workspace_id, meta={"error": "cursor_out_of_range"}, t0=t0)
        return _err("VALIDATION_ERROR", "cursor is out of range.")

    page = q[start_pos:start_pos + limit]
    next_pos = start_pos + len(page)
    has_more = next_pos < len(q)
    next_cursor = None
    if has_more:
        next_cursor = _encode_cursor({
            "v": 1,
            "pos": next_pos,
            "sort_by": sort_by_eff,
            "sort_order": sort_order_eff,
            "workspace_id": workspace_id,
            "status": status,
            "search": search,
        })

    resp = {
        "results": page,
        "meta": {
            "total": len(q),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by_eff,
            "sort_order": sort_order_eff,
        }
    }

    _log_request(endpoint, 200, workspace_id_used=used_workspace_id, meta={"returned": len(page), "total": len(q)}, t0=t0)
    return resp
